# ─── CHEMINS DE DÉTECTION ET IDS WINGET ───────────────────────────────────────
LOGICIELS = {
    "firefox": {
        # « Mozilla.Firefox » est le paquet en-US : c'est lui qui installait un
        # Firefox en ANGLAIS. Mozilla publie un paquet winget PAR LANGUE, d'où
        # le suffixe .fr. (Il n'existe pas de fr-CA chez Mozilla : la locale
        # française pour Firefox est « fr », y compris au Canada.)
        "winget_id": "Mozilla.Firefox.fr",
        # Repli en MSI : déployable, idempotent, et cohérent avec les stratégies
        # Firefox posées au registre. Le nom de produit est bien
        # « firefox-msi-latest-ssl » — « os=win64-msi » renvoie un 404.
        "dl_url":    "https://download.mozilla.org/?product=firefox-msi-latest-ssl&os=win64&lang=fr",
        "dl_args":   [],                  # MSI : arguments gérés par msiexec
        # Ancien installeur .exe conservé en 2e repli si l'URL MSI change.
        "dl_url_legacy":  "https://download.mozilla.org/?product=firefox-latest-ssl&os=win64&lang=fr",
        "dl_args_legacy": ["/S"],
        "paths": [
            r"C:\Program Files\Mozilla Firefox\firefox.exe",
            r"C:\Program Files (x86)\Mozilla Firefox\firefox.exe",
        ],
        "reg_patterns": ["Mozilla Firefox"],
    },
    "chrome": {
        "winget_id": "Google.Chrome",
        # MSI Chrome Enterprise : installation machine déterministe, contrairement
        # à chrome_installer.exe dont la portée dépend du contexte d'exécution.
        "dl_url":    "https://dl.google.com/dl/chrome/install/googlechromestandaloneenterprise64.msi",
        "dl_args":   [],                  # MSI
        "dl_url_legacy":  "https://dl.google.com/chrome/install/latest/chrome_installer.exe",
        "dl_args_legacy": ["/silent", "/install"],
        "paths": [
            r"C:\Program Files\Google\Chrome\Application\chrome.exe",
            r"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe",
            os.path.expandvars(r"%LOCALAPPDATA%\Google\Chrome\Application\chrome.exe"),
        ],
        "reg_patterns": ["Google Chrome"],
    },
    "slack": {
        "winget_id": "SlackTechnologies.Slack",
        # Portée MACHINE volontaire : en portée machine, winget sert un paquet
        # MSIX (Slack.msix) qui est provisionné pour TOUS les profils — c'est
        # exactement ce qu'il faut en provisionnement. En portée utilisateur,
        # Slack n'atterrirait que dans le profil du technicien.
        # Pas de dl_url : slack.com/ssb/download-win64-msi redirige vers un
        # fichier absent du CDN Slack (404 vérifié) — repli inutilisable.
        "paths": [
            os.path.expandvars(r"%LOCALAPPDATA%\slack\slack.exe"),
            os.path.expandvars(r"%LOCALAPPDATA%\Programs\slack\slack.exe"),
            r"C:\Program Files\Slack\slack.exe",
            r"C:\Program Files (x86)\Slack\slack.exe",
        ],
        # Installé en MSIX, Slack ne pose AUCUN des chemins ci-dessus (il vit dans
        # C:\Program Files\WindowsApps). La détection repose donc sur le registre
        # (DisplayName « Slack ») et sur le nom de paquet Appx ci-dessous.
        "reg_patterns": ["Slack"],
        "appx_name": "*Slack*",
    },
    "adobe": {
        "winget_id": "Adobe.Acrobat.Reader.64-bit",
        "paths": [
            r"C:\Program Files\Adobe\Acrobat DC\Acrobat\Acrobat.exe",
            r"C:\Program Files (x86)\Adobe\Acrobat Reader DC\Reader\AcroRd32.exe",
        ],
        "reg_patterns": ["Adobe Acrobat"],
    },
    "box_for_office": {
        "winget_id": "Box.BoxForOffice",
        "paths": [
            r"C:\Program Files\Box\Box for Office\BoxForOffice.exe",
            r"C:\Program Files (x86)\Box\Box for Office\BoxForOffice.exe",
            os.path.expandvars(r"%LOCALAPPDATA%\Box\Box for Office\BoxForOffice.exe"),
            r"C:\Program Files\Box\Box for Office",
            r"C:\Program Files (x86)\Box\Box for Office",
        ],
        "reg_patterns": ["Box for Office"],
    },
    "box_tools": {
        "winget_id": "Box.BoxTools",
        "paths": [
            r"C:\Program Files\Box\Box Tools\BoxTools.exe",
            r"C:\Program Files (x86)\Box\Box Tools\BoxTools.exe",
            os.path.expandvars(r"%LOCALAPPDATA%\Box\Box Tools\BoxTools.exe"),
            r"C:\Program Files\Box\Box Tools",
            r"C:\Program Files (x86)\Box\Box Tools",
        ],
        "reg_patterns": ["Box Tools"],
    },
    "intel_dsa": {
        # winget en primaire : identifiant versionné et signé, contrairement à
        # l'URL dsadata.intel.com qui pointe toujours sur « le dernier » installeur
        # sans garantie de forme. Le téléchargement direct reste en repli.
        "winget_id": "Intel.IntelDriverAndSupportAssistant",
        "dl_url":          "https://dsadata.intel.com/installer",
        "dl_url_fallback": "https://www.intel.com/content/www/us/en/support/intel-driver-and-support-assistant.html",
        "dl_args":   ["-s", "-norestart"],
        # Chemins couvrant toutes les versions d'Intel DSA :
        # - v22 et antérieurs : "Driver and Support Assistant\"
        # - v23+ : dossier renommé "DSA\"
        "paths": [
            r"C:\Program Files\Intel\Driver and Support Assistant\DSAService.exe",
            r"C:\Program Files\Intel\Driver and Support Assistant\DSALauncher.exe",
            r"C:\Program Files (x86)\Intel\Driver and Support Assistant\DSAService.exe",
            r"C:\Program Files\Intel\DSA\DSAService.exe",
            r"C:\Program Files\Intel\DSA\dsa.exe",
            r"C:\Program Files\Intel\DSA\isrv.exe",
            r"C:\Program Files\Intel\DSA\DSALauncher.exe",
        ],
        "service_name": "DSAService",   # nom du service Windows à vérifier en fallback
        "reg_patterns": ["Intel Driver & Support Assistant", "Intel DSA"],
    },
    "office": {
        "winget_id": "Microsoft.Office",
        "paths": [
            r"C:\Program Files\Microsoft Office\root\Office16\WINWORD.EXE",
            r"C:\Program Files (x86)\Microsoft Office\root\Office16\WINWORD.EXE",
        ],
    },
}

