# FONCTIONS UTILITAIRES WINDOWS
# ═══════════════════════════════════════════════════════════════════════════════

def get_desktop() -> Path:
    """Retourne le vrai chemin du bureau Windows (gère GPO, redirection, langue)."""
    try:
        import ctypes.wintypes
        buf = ctypes.create_unicode_buffer(ctypes.wintypes.MAX_PATH)
        # CSIDL_DESKTOPDIRECTORY = 0x0010
        ctypes.windll.shell32.SHGetFolderPathW(None, 0x0010, None, 0, buf)
        return Path(buf.value)
    except Exception:
        pass
    # Fallback registre
    try:
        key = winreg.OpenKey(
            winreg.HKEY_CURRENT_USER,
            r"Software\Microsoft\Windows\CurrentVersion\Explorer\Shell Folders"
        )
        val = winreg.QueryValueEx(key, "Desktop")[0]
        winreg.CloseKey(key)
        return Path(val)
    except Exception:
        return Path(os.path.expanduser("~/Desktop"))


def get_windows_build() -> tuple[str, str]:
    """Retourne (build, display_version) depuis le registre Windows.
    Ex : ("26100", "24H2"). Fallback sûr si clé absente.
    """
    try:
        with winreg.OpenKey(
            winreg.HKEY_LOCAL_MACHINE,
            r"SOFTWARE\Microsoft\Windows NT\CurrentVersion"
        ) as key:
            build   = winreg.QueryValueEx(key, "CurrentBuildNumber")[0]
            version = winreg.QueryValueEx(key, "DisplayVersion")[0]
        return str(build), str(version)
    except Exception:
        return "0", "Inconnu"


def run_cmd(cmd: list[str], capture: bool = True,
            timeout: int = 1800,
            env_extra: dict | None = None) -> tuple[int, str]:
    """Exécute une commande subprocess et retourne (code, output).

    Forçage UTF-8 complet :
    - PYTHONIOENCODING=utf-8        → encodage Python
    - PYTHONUTF8=1                  → mode UTF-8 Python 3.7+
    - chcp 65001 via env COMSPEC    → page de code console Windows
    - $OutputEncoding + [Console]   → encodage sortie PowerShell
    Sans ça, Windows FR utilise CP850/CP1252 et les accents/émojis sont corrompus.

    env_extra : variables d'environnement supplémentaires (ex. valeurs passées à un
    script PowerShell sans interpolation dans le corps du script — cf. renommage).
    """
    try:
        env = os.environ.copy()
        env["PYTHONIOENCODING"] = "utf-8"
        env["PYTHONUTF8"]       = "1"
        if env_extra:
            env.update({str(k): str(v) for k, v in env_extra.items()})

        # Si c'est un appel PowerShell, injecter le forçage UTF-8 en tête de commande.
        # On détecte via cmd[0] (powershell / pwsh).
        actual_cmd = list(cmd)
        exe = os.path.basename(actual_cmd[0]).lower()
        if exe in ("powershell.exe", "powershell", "pwsh.exe", "pwsh"):
            # Trouver l'index du -Command ou -File pour injecter avant le script
            utf8_prefix = (
                "[Console]::OutputEncoding=[System.Text.Encoding]::UTF8;"
                "$OutputEncoding=[System.Text.Encoding]::UTF8;"
                "$PSDefaultParameterValues['Out-File:Encoding']='utf8';"
            )
            try:
                cmd_idx = next(
                    i for i, a in enumerate(actual_cmd)
                    if a.lower() in ("-command", "-c")
                )
                # Injecter le prefix avant le script utilisateur
                actual_cmd[cmd_idx + 1] = utf8_prefix + actual_cmd[cmd_idx + 1]
            except StopIteration:
                pass  # pas de -Command trouvé (ex: -File), on laisse tel quel

        # CREATE_NO_WINDOW (0x08000000) : empêche chaque enfant console
        # (winget, powershell, cmd…) d'ouvrir sa propre fenêtre lorsque le
        # processus parent tourne sous pythonw.exe (sans console).
        result = subprocess.run(
            actual_cmd, capture_output=capture, text=True,
            encoding="utf-8", errors="replace", env=env,
            timeout=timeout, creationflags=0x08000000
        )
        # Windows retourne les codes HRESULT comme uint32, mais winget/PS
        # les définit en int32 signé — convertir pour correspondre à la table.
        code = result.returncode
        if code > 0x7FFFFFFF:
            code = code - 0x100000000
        return code, (result.stdout or "") + (result.stderr or "")
    except subprocess.TimeoutExpired:
        return -1, f"Délai dépassé ({timeout}s) : {cmd[0]}"
    except FileNotFoundError:
        return -1, f"Commande introuvable: {cmd[0]}"
    except Exception as exc:
        return -1, str(exc)


def reg_set(hive, path: str, name: str, value, vtype=winreg.REG_SZ):
    try:
        key = winreg.CreateKeyEx(hive, path, 0, winreg.KEY_SET_VALUE)
        winreg.SetValueEx(key, name, 0, vtype, value)
        winreg.CloseKey(key)
        return True
    except Exception:
        return False


def winget_exit_desc(code: int) -> tuple[str, str]:
    """Retourne (niveau, description) pour un code de sortie winget.
    Codes issus de la documentation officielle winget + codes HRESULT Windows.
    La conversion uint32→int32 est faite dans run_cmd avant d'arriver ici.
    """
    descriptions = {
        # ── Succès ────────────────────────────────────────────────────────────
        0:            ("OK",   "Succès"),
        3010:         ("OK",   "Succès — redémarrage requis"),
        1641:         ("OK",   "Succès — redémarrage initié"),
        # ── Skip (déjà installé / à jour) ────────────────────────────────────
        -1978335212:  ("SKIP", "Déjà installé"),
        -1978335189:  ("SKIP", "Déjà à jour / pas de mise à jour disponible"),
        -1978335140:  ("SKIP", "Aucune mise à jour applicable"),
        # ── Erreurs package / source ──────────────────────────────────────────
        # NB : -1978335215 (hash de manifeste périmé) est défini plus bas, dans la
        # section « applicabilité ». Ne pas le redéclarer ici : Python conserve la
        # DERNIÈRE occurrence, et le doublon rendait cette entrée-ci silencieusement
        # morte.
        -1978335214:  ("FAIL", "Plusieurs packages correspondent — préciser l'ID"),
        -1978335213:  ("FAIL", "Aucun résultat pour cette recherche"),
        -1978335231:  ("FAIL", "Source introuvable"),
        -1978335230:  ("FAIL", "Source déjà existante"),
        -1978335229:  ("FAIL", "Source invalide"),
        -1978335228:  ("FAIL", "Certificat de source invalide"),
        -1978335227:  ("FAIL", "Source désactivée"),
        -1978335232:  ("FAIL", "Winget non initialisé / sources non acceptées"),
        # ── Erreurs d'installation ────────────────────────────────────────────
        -1978334971:  ("FAIL", "Espace disque insuffisant"),   # 0x8A150105 (et non 0x8A150101)
        -1978334960:  ("FAIL", "Téléchargement échoué"),
        -1978334959:  ("FAIL", "Hash invalide — fichier corrompu ou modifié"),
        -1978334958:  ("FAIL", "Impossible de lancer l'installeur"),
        # 0x8A150101-0103 : les VRAIS codes de verrou (réessayés, cf. WINGET_TRANSIENT)
        -1978334975:  ("FAIL", "Application en cours d'exécution — la fermer puis réessayer"),
        -1978334974:  ("FAIL", "Une autre installation est déjà en cours"),
        -1978334973:  ("FAIL", "Un ou plusieurs fichiers sont en cours d'utilisation"),
        # 0x8A150113 : condition permanente — ne PAS réessayer.
        -1978334957:  ("FAIL", "Paquet non supporté par ce système"),
        -1978334956:  ("FAIL", "Annulé par l'utilisateur"),
        -1978334955:  ("FAIL", "Installeur introuvable après téléchargement"),
        -1978334954:  ("FAIL", "Mauvais type d'installeur pour ce système"),
        -1978334953:  ("FAIL", "Politique d'installation bloquée (GPO)"),
        -1978334948:  ("FAIL", "Dépendance manquante"),
        -1978334947:  ("FAIL", "Impossible de désinstaller la version précédente"),
        -1978334946:  ("FAIL", "Conflit avec un package existant"),
        # ── Erreurs de manifeste / applicabilité ──────────────────────────────
        -1978335216:  ("FAIL", "Aucun installeur applicable à ce système "
                               "(architecture, portée ou version Windows)"),
        -1978335215:  ("FAIL", "Hash du manifeste périmé (installeur mis à jour "
                               "côté éditeur)"),
        # ── Erreurs de configuration / droits ────────────────────────────────
        -1978335008:  ("FAIL", "Droits insuffisants (relancer en admin)"),
        -1978335007:  ("FAIL", "Volume chiffré non supporté"),
        -1978335006:  ("FAIL", "Chemin de destination invalide"),
        -1978335005:  ("FAIL", "Architecture incompatible (ARM/x64/x86)"),
        -1978335004:  ("FAIL", "Version Windows incompatible"),
        -1978335003:  ("FAIL", "Accord de licence non accepté"),
        # ── Erreurs réseau ────────────────────────────────────────────────────
        -1978286079:  ("FAIL", "Erreur réseau — vérifier la connexion internet"),
        -1978286078:  ("FAIL", "Délai de connexion dépassé"),
    }
    return descriptions.get(code, ("FAIL", f"Code HRESULT inconnu : {code} (0x{code & 0xFFFFFFFF:08X})"))


# ═══════════════════════════════════════════════════════════════════════════════
# WORKER THREAD — LOGIQUE D'INSTALLATION
# ═══════════════════════════════════════════════════════════════════════════════

def is_installed_via_registry(display_name_patterns: list[str]) -> bool:
    """Vérifie si un logiciel est installé en cherchant son nom dans les clés
    Uninstall du registre (HKLM 64-bit, HKLM 32-bit, HKCU).
    Reproduit la logique de vérification registre du PS1 pour Box for Office / Box Tools.
    Utilise des context managers (with) pour garantir la fermeture des handles,
    même en cas d'exception intermédiaire.
    """
    reg_paths = [
        (winreg.HKEY_LOCAL_MACHINE,
         r"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"),
        (winreg.HKEY_LOCAL_MACHINE,
         r"SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall"),
        (winreg.HKEY_CURRENT_USER,
         r"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"),
    ]
    for hive, path in reg_paths:
        try:
            with winreg.OpenKey(hive, path) as key:
                count = winreg.QueryInfoKey(key)[0]
                for i in range(count):
                    try:
                        subkey_name = winreg.EnumKey(key, i)
                        with winreg.OpenKey(key, subkey_name) as subkey:
                            try:
                                display_name = winreg.QueryValueEx(subkey, "DisplayName")[0]
                                for pattern in display_name_patterns:
                                    if pattern.lower() in display_name.lower():
                                        return True
                            except FileNotFoundError:
                                pass
                    except OSError:
                        continue
        except OSError:
            continue
    return False


def is_service_installed(service_name: str) -> bool:
    """Vérifie si un service Windows est installé (peu importe son état).
    Utilise `sc query` — disponible sur toutes les versions de Windows.
    """
    try:
        code, _ = run_cmd(["sc", "query", service_name], timeout=10)
        return code == 0
    except Exception:
        return False


def verify_authenticode(path: Path) -> tuple[bool, str]:
    """SEC-2 — Vérifie la signature Authenticode d'un exécutable Windows.

    Retourne (valide: bool, message: str).
    - Valid / UnknownError avec SignerCertificate présent → accepté.
    - NotSigned / HashMismatch / NotTrusted → rejeté.
    Utilise Get-AuthenticodeSignature (disponible sur toutes versions Windows).
    """
    ps = (
        f"$s = Get-AuthenticodeSignature -FilePath '{str(path)}';"
        "$s.Status.ToString() + '|' + "
        "$(if ($s.SignerCertificate) { $s.SignerCertificate.Subject } else { '' })"
    )
    try:
        code, out = run_cmd(
            ["powershell", "-NoProfile", "-ExecutionPolicy", "RemoteSigned",
             "-Command", ps],
            timeout=30
        )
        if code != 0:
            return False, f"Get-AuthenticodeSignature a échoué (code {code})"
        parts = out.strip().split("|", 1)
        status = parts[0].strip() if parts else "Unknown"
        subject = parts[1].strip() if len(parts) > 1 else ""
        # Statuts acceptables : le fichier est signé et la chaîne est valide.
        # UnknownError peut apparaître pour des certificats valides sur certains
        # proxy qui reconstruisent la chaîne TLS — on l'accepte si un sujet existe.
        if status == "Valid":
            return True, f"Signature valide — {subject}"
        if status == "UnknownError" and subject:
            return True, f"Signature présente (UnknownError) — {subject}"
        return False, f"Signature non valide : {status} — {subject or 'aucun certificat'}"
    except Exception as exc:
        return False, f"Vérification signature — erreur : {exc}"


class InstallWorker(QThread):
    """Thread d'arrière-plan qui exécute toutes les étapes d'installation."""

    sig_log      = pyqtSignal(str, str)        # (message, niveau)
    sig_step     = pyqtSignal(int, str, str)   # (index, état, détail)
    sig_progress = pyqtSignal(int, str)        # (pct, label)
    sig_done     = pyqtSignal()
    sig_pause    = pyqtSignal(str, str)        # (titre, message) — affiche une QMessageBox depuis le thread GUI

    def __init__(self, machine_info: dict):
        super().__init__()
        self.machine_info  = machine_info
        self.start_time    = datetime.now()
        # Utilisé par sig_pause : le worker attend que la GUI confirme via resume()
        self._pause_event  = threading.Event()
        self._pause_event.set()  # non bloquant par défaut
        # Arrêt propre : fermeture de fenêtre → request_stop() → run() s'arrête
        self._stop_event   = threading.Event()
        # Test winget effectué dans run() avant les étapes
        self._winget_ok: bool = False
        # Drapeaux de redémarrage, consolidés par _check_reboot_required().
        self._renamed: bool = False
        self._reboot_pending_seen: bool = False
        # Inventaire matériel, rempli par log_inventory() au début de run().
        # Conservé en mémoire pour un futur rapport de provisioning.
        self.inventory: dict = {}

        # Le log est écrit directement sur le bureau : c'est là que le technicien
        # le cherche en fin de provisionnement. Une version antérieure le plaçait
        # dans %PROGRAMDATA%\LGS\Logs avec des ACL restreintes ; en pratique cela
        # obligeait à passer par un raccourci pour le consulter, sans bénéfice réel.
        ts = self.start_time.strftime("%Y-%m-%d_%H-%M-%S")
        cn = self.machine_info.get("computer_name") or platform.node()
        self.log_path = get_desktop() / f"LGS_Log_Detaile_{cn}_{ts}.txt"
        build, version = get_windows_build()
        header = (
            "╔══════════════════════════════════════════════════════════════╗\n"
            "║          📋 LOG DÉTAILLÉ D'INSTALLATION LGS                 ║\n"
            "╚══════════════════════════════════════════════════════════════╝\n"
            f"Date/Heure début : {self.start_time.strftime('%Y-%m-%d %H:%M:%S')}\n"
            f"Ordinateur       : {cn}\n"
            f"Utilisateur      : {os.environ.get('USERNAME', 'Inconnu')}\n"
            f"Windows          : {version} (Build {build})\n"
            f"Python           : {sys.version.split()[0]}\n"
            f"LGS InstalleX    : v{INSTALLEX_VERSION}\n"
            f"Configuration    : {CONFIG_ORIGINE}\n\n"
            "Légende : ✅ OK | ❌ FAIL | ⚠️ WARN | ⏭️ SKIP | ℹ️ INFO | ↳ CMD\n"
            "══════════════════════════════════════════════════════════════════\n\n"
        )
        # Ouvrir le fichier une seule fois et le garder ouvert durant toute
        # l'installation — évite l'overhead d'open/close à chaque ligne de log.
        self._log_fh = None
        try:
            self._log_fh = open(self.log_path, "a", encoding="utf-8-sig", buffering=1)
            self._log_fh.write(header)
            self._log_fh.flush()
        except Exception:
            self.log_path = None  # emplacement inaccessible — on continue sans fichier
            if self._log_fh:
                try:
                    self._log_fh.close()
                except Exception:
                    pass
            self._log_fh = None

    def _append_log_file(self, line: str):
        if self._log_fh is None:
            return
        try:
            self._log_fh.write(line + "\n")
            self._log_fh.flush()
        except Exception:
            pass  # ne jamais bloquer l'installation pour un problème de log

    def _close_log_file(self):
        """Ferme proprement le handle de log en fin d'installation."""
        if self._log_fh is not None:
            try:
                self._log_fh.close()
            except Exception:
                pass
            self._log_fh = None

    # ── helpers de log ────────────────────────────────────────────────────────

    def log(self, msg: str, level: str = "INFO"):
        ts = datetime.now().strftime("%H:%M:%S")
        icons = {
            "OK":      "✅ [OK  ]",
            "WARN":    "⚠️  [WARN]",
            "FAIL":    "❌ [FAIL]",
            "SKIP":    "⏭️  [SKIP]",
            "CMD":     "   ↳ [CMD ]",
            "SECTION": "════════════════════════════════════════",
            "INFO":    "ℹ️  [INFO]",
        }
        prefix = icons.get(level, "ℹ️  [INFO]")
        if level == "SECTION":
            line = f"\n{prefix}\n  {msg}\n{prefix}"
        else:
            line = f"{ts} {prefix} {msg}"
        self._append_log_file(line)
        self.sig_log.emit(msg, level)

    def log_winget(self, pkg: str, code: int):
        level, desc = winget_exit_desc(code)
        self.log(f"{pkg} — winget exit code: {code} ({desc})", level)

    # ── progression ───────────────────────────────────────────────────────────

    def step(self, idx: int, state: str, detail: str = ""):
        self.sig_step.emit(idx, state, detail)

    def progress(self, pct: int, label: str):
        self.sig_progress.emit(pct, label)

    def _wait_for_user(self, titre: str, message: str):
        """Émet sig_pause (→ GUI affiche une QMessageBox) et bloque le worker
        jusqu'à ce que l'utilisateur clique OK. Thread-safe.
        """
        self._pause_event.clear()
        self.sig_pause.emit(titre, message)
        self._pause_event.wait()  # débloqué par InstalleXWindow via resume()

    def resume(self):
        """Appelé par le slot GUI quand l'utilisateur clique OK sur la pause."""
        self._pause_event.set()

    def request_stop(self):
        """Demande l'arrêt propre du worker (fermeture fenêtre).
        Débloque aussi _pause_event pour éviter un deadlock si l'utilisateur
        ferme pendant une pause Box User Agreement.
        """
        self._stop_event.set()
        self._pause_event.set()  # débloque _wait_for_user si en attente

    def _check_stop(self):
        """Lève une exception si l'arrêt a été demandé.
        À appeler entre les étapes dans run() pour un arrêt propre.
        """
        if self._stop_event.is_set():
            raise InterruptedError("Installation interrompue par fermeture de la fenêtre.")

    # ─────────────────────────────────────────────────────────────────────────
    # ÉTAPE 0 — Diagnostic système (déjà fait avant le thread)
    # ─────────────────────────────────────────────────────────────────────────

    # ─────────────────────────────────────────────────────────────────────────
    # ÉTAPE 1 — Création des dossiers
    # ─────────────────────────────────────────────────────────────────────────

    # ─────────────────────────────────────────────────────────────────────────
    # PROTECTION ANTI-VEILLE
    # ─────────────────────────────────────────────────────────────────────────

    def _save_and_disable_sleep(self):
        """Sauvegarde les paramètres de veille courants et les désactive
        pour éviter que la machine se mette en veille pendant l'installation.
        Reproduit la logique PS1 : powercfg /query pour lire, puis /change 0.
        """
        self.log("PROTECTION VEILLE", "SECTION")
        self._original_power: dict | None = None
        try:
            def _query(setting: str, field: str) -> str:
                code, out = run_cmd(
                    ["powercfg", "/query", "SCHEME_CURRENT", *setting.split()],
                    timeout=10
                )
                for line in out.splitlines():
                    if field in line:
                        return line.strip().split()[-1]
                return "0x00000000"

            standby_ac = _query("SUB_SLEEP STANDBYIDLE", "Current AC Power Setting Index:")
            standby_dc = _query("SUB_SLEEP STANDBYIDLE", "Current DC Power Setting Index:")
            monitor_ac = _query("SUB_VIDEO VIDEOIDLE",   "Current AC Power Setting Index:")
            monitor_dc = _query("SUB_VIDEO VIDEOIDLE",   "Current DC Power Setting Index:")

            self._original_power = {
                "standby_ac": standby_ac,
                "standby_dc": standby_dc,
                "monitor_ac": monitor_ac,
                "monitor_dc": monitor_dc,
            }

            run_cmd(["powercfg", "/change", "standby-timeout-ac", "0"], timeout=10)
            run_cmd(["powercfg", "/change", "standby-timeout-dc", "0"], timeout=10)
            run_cmd(["powercfg", "/change", "monitor-timeout-ac", "0"], timeout=10)
            run_cmd(["powercfg", "/change", "monitor-timeout-dc", "0"], timeout=10)
            self.log("Protection contre la veille activée (paramètres originaux sauvegardés)", "OK")
        except Exception as exc:
            self.log(f"Protection veille : impossible d'activer — {exc}", "WARN")

    def _restore_power_settings(self):
        """Restaure les paramètres de veille sauvegardés.
        Convertit les valeurs hex registre en minutes (÷ 60 secondes).
        Fallback sur des valeurs raisonnables si la conversion échoue.
        """
        if self._original_power is None:
            return
        try:
            def _hex_to_minutes(hex_str: str) -> int:
                try:
                    seconds = int(hex_str, 16)
                    return max(0, round(seconds / 60))
                except (ValueError, TypeError):
                    return 0

            # Le moniteur ne doit pas s'éteindre AVANT l'écran de veille (10 min),
            # sinon l'écran devient noir sans jamais afficher l'économiseur. Sur
            # secteur, on garantit >= 15 min pour que le Ribbons soit visible.
            ac_standby = _hex_to_minutes(self._original_power["standby_ac"]) or 30
            dc_standby = _hex_to_minutes(self._original_power["standby_dc"]) or 15
            ac_monitor = max(_hex_to_minutes(self._original_power["monitor_ac"]) or 15, 15)
            dc_monitor = _hex_to_minutes(self._original_power["monitor_dc"]) or 5

            run_cmd(["powercfg", "/change", "standby-timeout-ac", str(ac_standby)], timeout=10)
            run_cmd(["powercfg", "/change", "standby-timeout-dc", str(dc_standby)], timeout=10)
            run_cmd(["powercfg", "/change", "monitor-timeout-ac", str(ac_monitor)], timeout=10)
            run_cmd(["powercfg", "/change", "monitor-timeout-dc", str(dc_monitor)], timeout=10)
            self.log(
                f"Veille restaurée : standby AC={ac_standby}min DC={dc_standby}min, "
                f"moniteur AC={ac_monitor}min DC={dc_monitor}min", "OK"
            )
        except Exception as exc:
            self.log(f"Restauration veille — erreur : {exc}", "WARN")

    # ─────────────────────────────────────────────────────────────────────────
    # ÉTAPE 0 → 1
    # ─────────────────────────────────────────────────────────────────────────

    def step1_folders(self):
        self.step(1, "active", "Création des dossiers...")
        self.log("CRÉATION DES DOSSIERS", "SECTION")

        desktop = get_desktop()
        cat_path = desktop / "CAT"
        try:
            if cat_path.exists():
                self.log(f"Dossier CAT déjà présent — conservé : {cat_path}", "SKIP")
            else:
                cat_path.mkdir(parents=True, exist_ok=True)
                self.log(f"Dossier créé : {cat_path}", "OK")
        except Exception as exc:
            self.log(f"Erreur création dossier CAT : {exc}", "FAIL")

        self.step(1, "done", "Dossier CAT prêt")
        self.progress(2, "Étape 2/11 — Fichiers de documentation")

    # ─────────────────────────────────────────────────────────────────────────
    # ÉTAPE 2 — Fichiers de documentation (embedded)
    # ─────────────────────────────────────────────────────────────────────────

    def step2_docs(self):
        self.step(2, "active", "Extraction des fichiers...")
        self.log("FICHIERS EMBARQUÉS", "SECTION")

        cat_path = get_desktop() / "CAT"
        cat_path.mkdir(parents=True, exist_ok=True)

        for nom, b64 in FICHIERS_EMBARQUES.items():
            dest = cat_path / nom
            try:
                dest.write_bytes(base64.b64decode(b64))
                self.log(f"Extrait : {nom}", "OK")
            except Exception as exc:
                self.log(f"Erreur extraction {nom} : {exc}", "FAIL")

        self.step(2, "done", f"{len(FICHIERS_EMBARQUES)} fichier(s) extraits")
        self.progress(3, "Étape 3/11 — Bureau utilisateur")


    def step3_shortcuts(self):
        self.step(3, "active", "Vérification du bureau...")
        self.log("BUREAU UTILISATEUR", "SECTION")

        desktop = get_desktop()
        lnk     = desktop / "CAT.lnk"

        # Le dossier CAT est créé à l'étape 2 DIRECTEMENT sur le bureau : un
        # raccourci vers lui, posé sur ce même bureau, ne fait que dupliquer
        # l'icône. On ne le crée donc plus.
        # On supprime en revanche celui laissé par les versions précédentes, pour
        # que les postes déjà provisionnés se nettoient à la prochaine exécution.
        if lnk.exists():
            try:
                lnk.unlink()
                self.log("Raccourci CAT redondant supprimé du bureau.", "OK")
            except Exception as exc:
                self.log(f"Raccourci CAT — suppression impossible : {exc}", "WARN")
        else:
            self.log("Dossier CAT accessible directement sur le bureau.", "INFO")

        self.step(3, "done", "Bureau vérifié")
        self.progress(4, "Étape 4/11 — Nom d'ordinateur")

    # ─────────────────────────────────────────────────────────────────────────
    # ÉTAPE 4 — Nom d'ordinateur
    # ─────────────────────────────────────────────────────────────────────────

    def step4_computer_name(self):
        self.step(4, "active", "Vérification du nom...")
        self.log("NOM D'ORDINATEUR", "SECTION")

        new_name = self.machine_info.get("computer_name", "").strip()
        current  = platform.node()
        self.log(f"Nom actuel : {current}", "INFO")

        # Validation stricte (limite NetBIOS : 15 car., lettres/chiffres/tirets)
        # — empêche toute injection dans la commande PowerShell ci-dessous.
        # IMPORTANT : cette regex DOIT rester identique à celle de SetupDialog._launch()
        # (double validation : GUI au clic, thread à l'exécution).
        # Si tu modifies l'une, modifie l'autre.
        if new_name and not re.fullmatch(r"[A-Za-z0-9-]{1,15}", new_name):
            self.log(
                f"Nom invalide : '{new_name}' — lettres, chiffres et tirets "
                "seulement, 15 caractères max. Renommage ignoré.", "FAIL"
            )
            new_name = ""

        if new_name and new_name != current:
            # On évite Rename-Computer (PowerShell) qui peut envoyer WM_ENDSESSION
            # ou InitiateSystemShutdown sur certaines versions Windows, tuant la GUI.
            # Solution : écrire directement dans le registre + WMI SetComputerName,
            # sans aucun signal de redémarrage. Le changement est effectif après reboot.
            #
            # SEC-1 : le nom est passé via une VARIABLE D'ENVIRONNEMENT ($env:INSTALLEX_NEW_NAME),
            # jamais interpolé dans le corps du script → aucun risque d'injection PowerShell.
            # (L'ancienne approche `-Command <script> -ArgumentList <nom>` était inopérante :
            #  powershell.exe n'a pas de paramètre -ArgumentList, et le préfixe UTF-8 injecté
            #  cassait le param() — le nom n'était jamais lié, donc le renommage échouait.)
            ps_rename = r"""
try {
    $name = $env:INSTALLEX_NEW_NAME

    # 1) Registre — clés lues par Windows au prochain démarrage
    $path = 'HKLM:\SYSTEM\CurrentControlSet\Control\ComputerName\ComputerName'
    Set-ItemProperty -Path $path -Name ComputerName -Value $name -ErrorAction Stop

    $path2 = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
    Set-ItemProperty -Path $path2 -Name Hostname       -Value $name -ErrorAction SilentlyContinue
    Set-ItemProperty -Path $path2 -Name 'NV Hostname'  -Value $name -ErrorAction SilentlyContinue

    # 2) WMI SetComputerName (sans redémarrage, sans signal GUI)
    $cs = Get-WmiObject Win32_ComputerSystem
    $cs.Rename($name) | Out-Null

    Write-Host "OK"
} catch {
    Write-Host "FAIL: $($_.Exception.Message)"
}
"""
            code, out = run_cmd(
                ["powershell", "-NoProfile", "-ExecutionPolicy", "RemoteSigned",
                 "-Command", ps_rename],
                timeout=30, env_extra={"INSTALLEX_NEW_NAME": new_name}
            )
            out_clean = out.strip()
            if "OK" in out_clean and "FAIL" not in out_clean:
                self.log(f"Nom changé en : {new_name} (effectif au prochain redémarrage)", "OK")
                # Un renommage impose un redémarrage : mémorisé pour le
                # bilan final (_check_reboot_required).
                self._renamed = True
            else:
                detail = out_clean.replace("FAIL:", "").strip() or f"code {code}"
                self.log(f"Impossible de renommer : {detail}", "WARN")
        elif new_name:
            self.log(f"Nom déjà correct : {current}", "SKIP")
        else:
            self.log("Aucun nouveau nom fourni — étape ignorée.", "SKIP")

        self.step(4, "done", f"Nom : {new_name or current}")
        self.progress(5, "Étape 5/11 — Microsoft Office")

    # ─────────────────────────────────────────────────────────────────────────
    # ÉTAPE 4b — Nouvelle embauche : Box User Agreement
    # ─────────────────────────────────────────────────────────────────────────

    def step4b_nouvelle_embauche(self):
        """Ouvre Box IBM dans le navigateur par défaut et guide l'utilisateur
        pour accepter le User Agreement. Reproduit la logique PS1 :
        tentative d'automation SetForegroundWindow, puis boîte de dialogue
        de guidage si la fenêtre n'est pas trouvée.
        Exécuté uniquement si machine_info['nouvelle_embauche'] est True.
        """
        if not self.machine_info.get("nouvelle_embauche"):
            return

        self.log("NOUVELLE EMBAUCHE — BOX USER AGREEMENT", "SECTION")
        box_url = "https://ibm.ent.box.com/folder/0"
        try:
            import webbrowser
            webbrowser.open(box_url)
            self.log(f"Box ouvert dans le navigateur : {box_url}", "INFO")

            # Tentative d'automation : mettre la fenêtre du navigateur au premier plan
            # via ctypes user32 (même approche que PS1 WinAPI SetForegroundWindow).
            # ctypes est déjà importé globalement — pas de réimport local.
            try:
                EnumWindows    = ctypes.windll.user32.EnumWindows
                GetWindowTextW = ctypes.windll.user32.GetWindowTextW
                IsWindowVisible= ctypes.windll.user32.IsWindowVisible
                SetForeground  = ctypes.windll.user32.SetForegroundWindow
                ShowWindow     = ctypes.windll.user32.ShowWindow

                target_hwnd = ctypes.c_int(0)
                WNDENUMPROC = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_int, ctypes.c_int)

                def _enum(hwnd, _):
                    if not IsWindowVisible(hwnd):
                        return True
                    buf = ctypes.create_unicode_buffer(256)
                    GetWindowTextW(hwnd, buf, 256)
                    if "box" in buf.value.lower() or "ibm.ent.box" in buf.value.lower():
                        target_hwnd.value = hwnd
                        return False
                    return True

                time.sleep(1.5)  # laisser le navigateur s'ouvrir
                EnumWindows(WNDENUMPROC(_enum), 0)
                if target_hwnd.value:
                    ShowWindow(target_hwnd.value, 9)  # SW_RESTORE
                    SetForeground(target_hwnd.value)
                    self.log("Navigateur mis au premier plan.", "INFO")
            except Exception:
                pass  # automation non critique — on affiche quand même la boîte

            # Bloquer le worker et afficher une QMessageBox dans le thread GUI.
            # L'installation reprend seulement quand l'utilisateur clique OK.
            self._wait_for_user(
                "Nouvelle Embauche — Box User Agreement",
                "La page Box (IBM) a été ouverte dans votre navigateur.\n\n"
                "Veuillez cliquer sur le bouton 'Accept' ou 'J'accepte' du User Agreement,\n"
                "puis cliquez OK ici pour continuer l'installation."
            )
            self.log("Nouvelle Embauche — Box User Agreement : étape complétée", "OK")

        except Exception as exc:
            self.log(f"Nouvelle Embauche — erreur : {exc}", "WARN")

    # ─────────────────────────────────────────────────────────────────────────
    # ÉTAPE 5 — Microsoft Office
    # ─────────────────────────────────────────────────────────────────────────

    def step5_office(self):
        self.step(5, "active", "Installation de Microsoft 365 Apps...")
        self.log("MICROSOFT 365 APPS", "SECTION")

        office_paths = LOGICIELS["office"]["paths"]
        already = any(Path(p).exists() for p in office_paths)
        if already:
            self.log("Microsoft 365 Apps déjà installé.", "SKIP")
            self.step(5, "done", "Office déjà présent")
            self.progress(6, "Étape 6/11 — Logiciels")
            return

        # 1) winget d'abord : aucun fichier à pré-déposer, setup.exe téléchargé
        #    depuis le CDN Microsoft. Notre configuration.xml est passée via
        #    --custom /configure, donc le résultat est identique à l'ODT.
        ok = self._install_office_winget()
        if ok:
            self.log("Microsoft 365 Apps installé via winget.", "OK")
            self.step(5, "done", "Office installé")
            self.progress(6, "Étape 6/11 — Logiciels")
            return

        # 2) Repli ODT local — utile si winget est absent, si le poste n'a pas
        #    accès au CDN, ou en cas de « hash mismatch » du manifeste winget.
        self.log("Office — repli sur l'ODT local.", "INFO")
        ok = self._install_office_odt()
        if ok:
            self.log("Microsoft 365 Apps installé via ODT.", "OK")
            self.step(5, "done", "Office installé")
        else:
            self.log(
                "Échec winget ET ODT — voir le journal ci-dessus. "
                "Config manuelle : https://config.office.com", "FAIL"
            )
            self.step(5, "done", "Office : échec (manuel requis)")

        self.progress(6, "Étape 6/11 — Logiciels")

    def _install_office_winget(self) -> bool:
        """Installe Microsoft 365 Apps via winget, en lui passant NOTRE configuration.xml.

        Le paquet winget `Microsoft.Office` est en réalité le MÊME setup.exe Click-to-Run
        que l'ODT : winget se contente de le télécharger depuis le CDN Microsoft. On évite
        donc d'avoir à pré-déposer setup.exe dans C:\\LGS_Deploy\\ODT, tout en gardant le
        contrôle total (fr-ca, canal, RemoveMSI…) grâce à --custom "/configure <xml>".

        Sans --custom, winget installerait la configuration par défaut du manifeste
        (langue/apps non maîtrisées) — inacceptable pour un poste corpo.
        """
        if not self._winget_ok:
            self.log("Office — winget indisponible.", "WARN")
            return False

        work = Path(tempfile.gettempdir()) / "LGS_Office"
        work.mkdir(parents=True, exist_ok=True)
        cfg = work / "configuration.xml"
        try:
            cfg.write_text(self.ODT_CONFIG_XML, encoding="utf-8")
        except Exception as e:
            self.log(f"Office — écriture configuration.xml impossible : {e}", "WARN")
            return False

        self.log("Office — winget install Microsoft.Office (config fr-CA)", "CMD")
        # Pas de --silent ici : le mode silencieux vient de <Display Level="None"/>
        # dans le XML. Ajouter --silent ferait entrer les switches du manifeste en
        # conflit avec /configure.
        SUCCESS_CODES = (0, 3010, 1641)
        HASH_MISMATCH = -1978335215   # 0x8A150011 APPINSTALLER_CLI_ERROR_INSTALLER_HASH_MISMATCH

        def _run_winget(extra: list[str]) -> tuple[int, str]:
            return run_cmd([
                "winget", "install", "--id", "Microsoft.Office",
                "--exact",
                "--source", "winget",
                "--accept-package-agreements",
                "--accept-source-agreements",
                "--custom", f'/configure "{cfg}"',
            ] + extra, timeout=3600)

        code, out = _run_winget([])

        if code == HASH_MISMATCH:
            # Cause connue : le manifeste winget fige un hash alors que Microsoft
            # met à jour setup.exe sur son CDN — le paquet Microsoft.Office casse
            # donc périodiquement. Le binaire vient bien du CDN Microsoft en HTTPS,
            # et il est de toute façon vérifié par Authenticode au repli ODT.
            self.log("Office — hash du manifeste winget périmé, nouvelle tentative.", "WARN")
            code, out = _run_winget(["--ignore-security-hash"])

        if code not in SUCCESS_CODES:
            for line in (out or "").strip().splitlines()[:6]:
                if line.strip():
                    self.log(f"  winget: {line.strip()}", "CMD")
            # Échec fréquent : « Installer hash does not match » — le manifeste
            # winget référence un hash figé alors que Microsoft met à jour le
            # setup.exe sur son CDN. On bascule alors sur l'ODT local.
            self.log(f"Office — winget a échoué (code {code}).", "WARN")
            return False

        # Vérification réelle : winget peut retourner 0 alors que C2R a échoué.
        for _ in range(12):
            if any(Path(p).exists() for p in LOGICIELS["office"]["paths"]):
                return True
            time.sleep(10)
        self.log("Office — winget terminé mais Office introuvable.", "WARN")
        return False

    # ── Déploiement Microsoft 365 Apps for enterprise via l'ODT ───────────────
    # configuration.xml : M365 Apps entreprise, canal Current, x64, fr-CA (+en-us),
    # installation silencieuse, activation auto, suppression d'un ancien Office MSI.
    ODT_CONFIG_XML = (
        '<Configuration>\n'
        '  <Add OfficeClientEdition="64" Channel="Current">\n'
        '    <Product ID="O365ProPlusRetail">\n'
        '      <Language ID="fr-ca" />\n'
        '      <Language ID="en-us" />\n'
        '    </Product>\n'
        '  </Add>\n'
        '  <Property Name="SharedComputerLicensing" Value="0" />\n'
        '  <Property Name="AUTOACTIVATE" Value="1" />\n'
        '  <Property Name="FORCEAPPSHUTDOWN" Value="TRUE" />\n'
        '  <Updates Enabled="TRUE" Channel="Current" />\n'
        '  <Display Level="None" AcceptEULA="TRUE" />\n'
        '  <RemoveMSI />\n'
        '</Configuration>\n'
    )

    def _find_odt_setup(self):
        """Localise le setup.exe de l'Office Deployment Tool (fichier compagnon).

        Ordre : C:\\LGS_Deploy\\ODT (emplacement standard), puis dossier du script,
        sous-dossier ODT\\, et anciens chemins. Retourne un Path ou None.
        """
        candidates = [LGS_DEPLOY_DIR / "ODT" / "setup.exe"]
        try:
            script_dir = Path(os.path.abspath(sys.argv[0])).parent
            candidates += [script_dir / "setup.exe",
                           script_dir / "ODT" / "setup.exe"]
        except Exception:
            pass
        candidates += [Path(r"C:\ODT\setup.exe"),
                       Path(r"C:\Deploy\ODT\setup.exe")]
        for c in candidates:
            try:
                if c.exists():
                    return c
            except Exception:
                continue
        return None

    # setup.exe Click-to-Run servi par le CDN Office de Microsoft. C'est le même
    # binaire que celui extrait de l'ODT du Centre de téléchargement. Le domaine
    # officecdn.microsoft.com doit de toute façon être autorisé par le pare-feu,
    # sans quoi aucune installation Office ne peut aboutir.
    # Le fichier téléchargé est VÉRIFIÉ PAR AUTHENTICODE avant exécution : s'il
    # n'est pas signé Microsoft, il est rejeté.
    ODT_CDN_URL = "https://officecdn.microsoft.com/pr/wsus/setup.exe"

    # Microsoft Store — Lenovo COMMERCIAL Vantage (repli si le paquet de
    # déploiement Lenovo est absent du poste).
    # NE PAS confondre avec 9WZDNCRFJ4MV, la version GRAND PUBLIC : celle-ci
    # embarque la surveillance dark web et des fonctions promotionnelles, qui
    # n'ont rien à faire sur un poste d'entreprise.
    VANTAGE_STORE_ID = "9NR5B8GVVM13"

    def _download_odt_setup(self) -> Path | None:
        """Télécharge setup.exe (ODT) depuis le CDN Microsoft. None si échec.

        Évite d'avoir à déposer manuellement setup.exe dans C:\\LGS_Deploy\\ODT.
        """
        dest = Path(tempfile.gettempdir()) / "INSTALLEX_ODT" / "setup.exe"
        self.log("ODT — téléchargement de setup.exe depuis le CDN Microsoft...", "CMD")
        ok, msg = download_file(self.ODT_CDN_URL, dest, timeout=300)
        if not ok:
            self.log(f"ODT — téléchargement échoué : {msg}", "WARN")
            return None

        sig_ok, sig_msg = verify_authenticode(dest)
        if not sig_ok:
            self.log(f"ODT — signature invalide : {sig_msg} — fichier rejeté.", "FAIL")
            try:
                dest.unlink()
            except Exception:
                pass
            return None
        self.log(f"ODT — setup.exe {msg}, signature vérifiée ({sig_msg}).", "OK")
        return dest

    def _install_office_odt(self) -> bool:
        # 1. Localiser l'ODT (setup.exe) : dépôt local d'abord, sinon CDN Microsoft.
        setup = self._find_odt_setup()
        if setup is None:
            setup = self._download_odt_setup()
        if setup is None:
            self.log(
                "ODT indisponible (ni local, ni téléchargeable). "
                "Déposez le setup.exe de l'Office Deployment Tool dans "
                "C:\\LGS_Deploy\\ODT\\, puis relancez. Téléchargement : "
                "https://www.microsoft.com/download/details.aspx?id=49117",
                "WARN"
            )
            return False
        self.log(f"ODT trouvé : {setup}", "OK")

        # 2. Écrire configuration.xml dans un dossier de travail temporaire.
        work = Path(os.environ.get("TEMP", r"C:\Windows\Temp")) / "INSTALLEX_ODT"
        try:
            work.mkdir(parents=True, exist_ok=True)
            cfg = work / "configuration.xml"
            cfg.write_text(self.ODT_CONFIG_XML, encoding="utf-8")
            self.log(f"configuration.xml écrit : {cfg}", "CMD")
        except Exception as e:
            self.log(f"Impossible d'écrire configuration.xml : {e}", "FAIL")
            return False

        # 3. Lancer l'installation. Le payload Office (~3,5 Go) est téléchargé
        #    depuis le CDN Office (officecdn.microsoft.com), qui n'est PAS soumis
        #    au certificate pinning de winget : l'erreur 0x8A15005E ne s'applique
        #    donc pas ici. Prévoir jusqu'à 60 min (réseau + installation).
        self.log("Lancement ODT : setup.exe /configure configuration.xml", "CMD")
        code, out = run_cmd([str(setup), "/configure", str(cfg)], timeout=3600)
        if out.strip():
            for line in out.strip().splitlines()[:5]:
                if line.strip():
                    self.log(f"  ODT: {line.strip()}", "CMD")

        # 4. Succès = code 0 ET WINWORD présent (l'ODT peut rendre 0 avant la
        #    fin réelle ; on vérifie donc aussi la présence sur disque).
        installed = any(Path(p).exists() for p in LOGICIELS["office"]["paths"])
        if code == 0 and installed:
            return True
        if installed:
            self.log("Office détecté malgré un code ODT non nul.", "WARN")
            return True
        self.log(f"ODT terminé (code {code}), Office non détecté.", "FAIL")
        return False

    # ─────────────────────────────────────────────────────────────────────────
    # ÉTAPE 6 — Logiciels (Firefox, Chrome, Slack, Adobe, Intel DSA)
    # ─────────────────────────────────────────────────────────────────────────

    # Codes transitoires : une autre installation MSI/C2R tient le verrou
    # Windows Installer. Fréquent quand deux paquets s'enchaînent (observé :
    # Slack lancé dans la même seconde que la fin de Chrome). Un simple délai
    # suffit — inutile de faire échouer le logiciel pour ça.
    # CORRECTIF : -1978334957 figurait ici comme « autre processus en cours ».
    # C'est en réalité 0x8A150113 INSTALL_SYSTEM_NOT_SUPPORTED (paquet non
    # supporté par le système) — une condition PERMANENTE : on perdait 3 essais
    # et 60 s d'attente pour un cas qui ne pouvait jamais se résoudre. Pendant ce
    # temps le vrai code de verrou, 0x8A150102 INSTALL_IN_PROGRESS, était absent
    # de la liste et n'était donc jamais réessayé — exactement le scénario que ce
    # mécanisme était censé couvrir.
    WINGET_TRANSIENT = (
        -1978334974,   # 0x8A150102 INSTALL_IN_PROGRESS — autre installation en cours
        -1978334975,   # 0x8A150101 INSTALL_PACKAGE_IN_USE — application en cours d'exécution
        -1978334973,   # 0x8A150103 INSTALL_FILE_IN_USE — fichier verrouillé
        -1978335215,   # 0x8A150011 INSTALLER_HASH_MISMATCH — hash de manifeste périmé
    )

    def _msstore_install(self, store_id: str, name: str) -> bool:
        """Installe un paquet depuis le Microsoft Store (source msstore).

        Utilisé en dernier recours seulement : la source msstore échoue avec
        0x8A15005E (certificate pinning) derrière un proxy à inspection SSL, et
        les paquets Store sont des MSIX — donc refusés sur les images où le
        déploiement AppX est restreint.
        """
        if not self._winget_ok:
            return False
        self.log(f"{name} — tentative via le Microsoft Store ({store_id})...", "CMD")
        # Pas de --scope : les paquets Store sont des MSIX et gèrent eux-mêmes
        # leur portée. L'imposer faisait échouer l'installation, exactement comme
        # pour Slack (-1978334957, « paquet non supporté par ce système »).
        code, out = run_cmd([
            "winget", "install", "--id", store_id,
            "--exact",
            "--source", "msstore",
            "--accept-package-agreements",
            "--accept-source-agreements",
        ], timeout=900)
        if code in (0, 3010, 1641):
            return True
        self.log_winget(f"{name} (Store)", code)
        for line in (out or "").strip().splitlines()[:4]:
            if line.strip():
                self.log(f"  msstore: {line.strip()}", "CMD")
        return False

    def _winget_install(self, pkg_id: str, name: str,
                        scope: str | None = "machine") -> bool:
        """Installe un paquet winget. Retourne True si l'installation est réussie.

        scope : portée demandée à winget (« machine » par défaut). Passer None pour
        les paquets qu'on veut explicitement en portée utilisateur.

        Deux codes déclenchent un réessai SANS --scope plutôt qu'un abandon, car
        l'un comme l'autre signifie « pas d'installeur exploitable POUR CETTE
        PORTÉE », alors qu'une autre portée conviendrait :

        - -1978335216 (0x8A150010) « aucun installeur applicable » ;
        - -1978334957 (0x8A150113) « paquet non supporté par ce système » — cas
          réel de Slack : en portée machine winget sert un MSIX, refusé par les
          images où le déploiement AppX est restreint, alors qu'un SlackSetup.exe
          parfaitement installable est proposé pour l'autre portée.
        """
        if not self._winget_ok:
            self.log(f"{name} — winget indisponible, installation ignorée.", "WARN")
            return False
        SUCCESS_CODES = (0, 3010, 1641, -1978335212, -1978335189, -1978335140)
        HASH_MISMATCH = -1978335215   # 0x8A150011 — hash de manifeste périmé
        NO_APPLICABLE = -1978335216   # 0x8A150010 — aucun installeur pour cette portée
        NOT_SUPPORTED = -1978334957   # 0x8A150113 — paquet non supporté par ce système
        SCOPE_RETRY   = (NO_APPLICABLE, NOT_SUPPORTED)
        base_cmd = [
            "winget", "install", "--id", pkg_id,
            "--exact",
            "--source", "winget",
            "--silent",
            "--accept-package-agreements",
            "--accept-source-agreements",
        ]

        code, out = 1, ""
        drop_scope = False               # passe à True après un code SCOPE_RETRY
        for attempt in range(1, 4):          # 3 tentatives maximum
            if attempt == 1:
                self.log(f"{name} — winget install {pkg_id}", "CMD")
            else:
                self.log(f"{name} — nouvelle tentative ({attempt}/3)...", "CMD")
            cmd = list(base_cmd)
            if scope and not drop_scope:
                cmd += ["--scope", scope]
            if code == HASH_MISMATCH:        # hash périmé : ignorer la vérif
                cmd.append("--ignore-security-hash")
            code, out = run_cmd(cmd, timeout=600)
            if code in SUCCESS_CODES:
                break
            if code in SCOPE_RETRY and scope and not drop_scope:
                drop_scope = True
                motif = ("aucun installeur en portée" if code == NO_APPLICABLE
                         else "paquet non supporté par ce système en portée")
                self.log(
                    f"{name} — {motif} « {scope} » ; nouvel essai sans --scope "
                    "(winget choisira l'installeur adapté).", "WARN"
                )
                continue                     # pas d'attente : ce n'est pas un verrou
            if code not in self.WINGET_TRANSIENT:
                break
            time.sleep(30)                   # laisser le verrou MSI se libérer

        self.log_winget(name, code)
        # Logger les premières lignes de sortie winget si échec — aide au diagnostic
        if code not in SUCCESS_CODES and out.strip():
            for line in out.strip().splitlines()[:5]:
                if line.strip():
                    self.log(f"  winget: {line.strip()}", "CMD")
        return code in SUCCESS_CODES

    def _soft_present(self, entry: dict) -> bool:
        """Un logiciel du catalogue LOGICIELS est-il déjà installé ?

        Combine chemins, clés Uninstall du registre et paquets MSIX/Appx. La
        détection par chemin seule ratait les installations dans un dossier
        inhabituel — et surtout les paquets MSIX, qui vivent sous
        C:\\Program Files\\WindowsApps et n'exposent aucun chemin classique
        (cas de Slack, servi en MSIX par winget en portée machine).
        """
        if any(Path(p).exists() for p in entry.get("paths", [])):
            return True
        pats = entry.get("reg_patterns")
        if pats and is_installed_via_registry(pats):
            return True
        appx = entry.get("appx_name")
        if appx:
            try:
                code, out = run_cmd(self._ps_encoded(
                    f"if (Get-AppxPackage -Name '{appx}') {{ Write-Output 'APPX=1' }}"
                ), timeout=45)
                if code == 0 and "APPX=1" in (out or ""):
                    return True
            except Exception:
                pass
        return False

    def _install_from_url(self, name: str, url: str, tmp_name: str,
                          args: list, detect_paths: list,
                          extra_headers: dict | None = None,
                          reg_patterns: list | None = None) -> bool:
        """Télécharge un installeur, l'exécute, puis confirme l'installation.

        - Le téléchargement passe par download_file() : contexte TLS enrichi des
          magasins Windows puis repli curl.exe/Schannel (indispensable derrière le
          proxy à inspection SSL).
        - Un fichier .msi est lancé via msiexec /i /qn /norestart ; les .exe
          reçoivent `args` tels quels.
        - La confirmation combine chemins ET registre, comme partout ailleurs.

        Retourne True si l'installation est confirmée, False sinon.
        """
        tmp = Path(tempfile.gettempdir()) / tmp_name
        try:
            self.log(f"Téléchargement {name}...", "CMD")
            ok_dl, msg_dl = download_file(url, tmp, timeout=300)
            if not ok_dl:
                self.log(f"{name} — téléchargement échoué : {msg_dl}", "WARN")
                return False
            # Vérification taille minimale : un fichier < 100 KB est presque
            # certainement une page d'erreur HTML, pas un installeur valide.
            file_size = tmp.stat().st_size
            if file_size < 100 * 1024:
                self.log(
                    f"{name} — fichier téléchargé trop petit ({file_size} octets), "
                    "installation annulée. URL inaccessible ?", "WARN"
                )
                return False
            # SEC-2 — vérification Authenticode avant exécution
            sig_ok, sig_msg = verify_authenticode(tmp)
            if sig_ok:
                self.log(f"{name} — {sig_msg}", "OK")
            else:
                self.log(f"{name} — signature invalide : {sig_msg} — installation annulée.", "FAIL")
                return False

            if tmp.suffix.lower() == ".msi":
                cmd = ["msiexec", "/i", str(tmp), "/qn", "/norestart"] + list(args)
            else:
                cmd = [str(tmp)] + list(args)
            code_i, out_i = run_cmd(cmd, timeout=900)
            if code_i not in (0, 3010, 1641):
                self.log(f"{name} — installeur terminé avec le code {code_i}.", "WARN")
                for line in (out_i or "").strip().splitlines()[:3]:
                    if line.strip():
                        self.log(f"  {name}: {line.strip()}", "CMD")

            # Vérification post-installation : chemins + registre.
            found = bool(detect_paths) and any(Path(p).exists() for p in detect_paths)
            if not found and reg_patterns:
                found = is_installed_via_registry(reg_patterns)
            if found:
                self.log(f"{name} installé avec succès.", "OK")
                return True
            if detect_paths or reg_patterns:
                self.log(f"{name} — introuvable après installation.", "WARN")
                return False
            # Aucun moyen de détection fourni : s'en remettre au code retour.
            if code_i in (0, 3010, 1641):
                self.log(f"{name} — installeur terminé (vérification manuelle recommandée).", "OK")
                return True
            return False
        except Exception as exc:
            self.log(f"{name} — erreur : {exc}", "FAIL")
            return False
        finally:
            try:
                tmp.unlink(missing_ok=True)
            except Exception:
                pass

    def step6_software(self):
        self.step(6, "active", "Installation des logiciels...")
        self.log("INSTALLATIONS LOGICIELS", "SECTION")

        # ── Firefox ───────────────────────────────────────────────────────────
        self.log("Installation de Firefox...", "INFO")
        ff = LOGICIELS["firefox"]
        if self._soft_present(ff):
            self.log("Firefox déjà installé.", "SKIP")
        else:
            # Méthode 1 : winget (préféré — gère les mises à jour auto)
            ok = self._winget_install(ff["winget_id"], "Firefox")
            # winget peut retourner 0 sans que le logiciel soit réellement présent :
            # on confirme avant de conclure (cf. le cas observé sur Office).
            if ok and not self._soft_present(ff):
                self.log("Firefox — winget signale un succès mais rien d'installé.", "WARN")
                ok = False
            if not ok:
                # Méthode 2 : MSI déployable
                ok = self._install_from_url(
                    "Firefox", ff["dl_url"], "Firefox_Setup.msi",
                    ff["dl_args"], ff["paths"], reg_patterns=ff.get("reg_patterns")
                )
            if not ok:
                # Méthode 3 : installeur .exe historique (si l'URL MSI a changé)
                self._install_from_url(
                    "Firefox (installeur .exe)", ff["dl_url_legacy"],
                    "Firefox_Setup.exe", ff["dl_args_legacy"], ff["paths"],
                    reg_patterns=ff.get("reg_patterns")
                )

        # ── Google Chrome ─────────────────────────────────────────────────────
        self.log("Installation de Google Chrome...", "INFO")
        ch = LOGICIELS["chrome"]
        if self._soft_present(ch):
            self.log("Google Chrome déjà installé.", "SKIP")
        else:
            # Méthode 1 : winget
            ok = self._winget_install(ch["winget_id"], "Chrome")
            if ok and not self._soft_present(ch):
                self.log("Chrome — winget signale un succès mais rien d'installé.", "WARN")
                ok = False
            if not ok:
                # Méthode 2 : MSI Chrome Enterprise (portée machine déterministe)
                ok = self._install_from_url(
                    "Chrome", ch["dl_url"], "Chrome_Enterprise.msi",
                    ch["dl_args"], ch["paths"], reg_patterns=ch.get("reg_patterns")
                )
            if not ok:
                # Méthode 3 : installeur grand public (si l'URL MSI a changé)
                self._install_from_url(
                    "Chrome (installeur .exe)", ch["dl_url_legacy"],
                    "Chrome_Installer.exe", ch["dl_args_legacy"], ch["paths"],
                    reg_patterns=ch.get("reg_patterns")
                )

        # ── Pages d'accueil www.lgs.com ───────────────────────────────────────
        self.log("Configuration page d'accueil www.lgs.com...", "INFO")
        homepage = CONFIG.get("homepage") or "https://www.lgs.com"
        homepage_keys = [
            (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Policies\Google\Chrome",
             "HomepageLocation",    homepage,    winreg.REG_SZ),
            (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Policies\Google\Chrome",
             "HomepageIsNewTabPage", 0,          winreg.REG_DWORD),
            (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Policies\Google\Chrome",
             "RestoreOnStartup",    4,           winreg.REG_DWORD),
            (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Policies\Google\Chrome\RestoreOnStartupURLs",
             "1",                   homepage,    winreg.REG_SZ),
            (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Policies\Microsoft\Edge",
             "HomepageLocation",    homepage,    winreg.REG_SZ),
            (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Policies\Microsoft\Edge",
             "HomepageIsNewTabPage", 0,          winreg.REG_DWORD),
            (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Policies\Mozilla\Firefox\Homepage",
             "URL",                 homepage,    winreg.REG_SZ),
        ]
        reg_errors = 0
        for hive, path, name, value, vtype in homepage_keys:
            if not reg_set(hive, path, name, value, vtype):
                self.log(f"Clé de registre non écrite : {path}\\{name}", "WARN")
                reg_errors += 1
        if reg_errors == 0:
            self.log(f"Page d'accueil configurée : {homepage}", "OK")
        else:
            self.log(f"Page d'accueil : {reg_errors} clé(s) non écrite(s) — vérifier les droits.", "WARN")

        # ── Slack ─────────────────────────────────────────────────────────────
        self.log("Installation de Slack...", "INFO")
        sl = LOGICIELS["slack"]
        if self._soft_present(sl):
            self.log("Slack déjà installé.", "SKIP")
        else:
            # Portée machine : winget sert alors le paquet MSIX de Slack,
            # provisionné pour TOUS les profils — le bon comportement en
            # provisionnement. (Vérifié : `winget show SlackTechnologies.Slack
            # --scope machine` renvoie bien un installeur de type msix, et
            # `--scope user` un SlackSetup.exe.)
            #
            # Sur les images où le déploiement AppX est restreint, ce MSIX est
            # refusé avec -1978334957 (0x8A150113, « paquet non supporté par ce
            # système »). _winget_install rebascule alors automatiquement sans
            # --scope, ce qui donne le SlackSetup.exe : Slack est bien installé,
            # mais pour le SEUL profil courant — d'où l'avertissement ci-dessous.
            # scope=None : on laisse winget choisir l'installeur. Imposer la
            # portée machine sert le MSIX, refusé par les images où le
            # déploiement AppX est restreint (-1978334957).
            ok = self._winget_install(sl["winget_id"], "Slack", scope=None)
            if self._soft_present(sl):
                # Distinguer MSIX (tous profils) et .exe (profil courant seul) :
                # dans le 2e cas l'utilisateur final devra installer Slack lui-même.
                # Les chemins classiques (%LOCALAPPDATA%\slack…) ne sont posés que
                # par l'installeur .exe : un MSIX vit dans WindowsApps et n'en
                # expose aucun. Leur présence signale donc l'installation .exe.
                install_exe = any(Path(p).exists() for p in sl["paths"])
                if install_exe:
                    self.log(
                        "Slack installé, mais via l'installeur .exe : présent "
                        "UNIQUEMENT pour la session courante. L'utilisateur final "
                        "devra l'installer à sa première ouverture de session.",
                        "WARN"
                    )
                else:
                    self.log("Slack installé (MSIX, tous les profils).", "OK")
            elif ok:
                self.log(
                    "Slack — winget signale un succès mais Slack reste "
                    "introuvable (ni chemin, ni registre, ni paquet MSIX).", "WARN"
                )
            else:
                self.log("Slack — installation non confirmée.", "WARN")

        # ── Box for Office ────────────────────────────────────────────────────
        self.log("Installation de Box for Office...", "INFO")
        bfo = LOGICIELS["box_for_office"]
        if self._soft_present(bfo):
            self.log("Box for Office déjà installé.", "SKIP")
        else:
            ok = self._winget_install(bfo["winget_id"], "Box for Office")
            if ok and not self._soft_present(bfo):
                self.log("Box for Office — winget signale un succès mais rien d'installé.", "WARN")
                ok = False
            if not ok:
                self.log(
                    "Box for Office — échec winget. "
                    "Installez manuellement : https://www.box.com/resources/downloads", "WARN"
                )

        # ── Box Tools ─────────────────────────────────────────────────────────
        self.log("Installation de Box Tools...", "INFO")
        bt = LOGICIELS["box_tools"]
        if self._soft_present(bt):
            self.log("Box Tools déjà installé.", "SKIP")
        else:
            # scope=None : Box Tools s'installe par utilisateur ; imposer la
            # portée machine faisait échouer winget faute d'installeur applicable.
            ok = self._winget_install(bt["winget_id"], "Box Tools", scope=None)
            if ok and not self._soft_present(bt):
                self.log("Box Tools — winget signale un succès mais rien d'installé.", "WARN")
                ok = False
            if not ok:
                self.log(
                    "Box Tools — échec winget. "
                    "Installez manuellement : https://www.box.com/resources/downloads", "WARN"
                )

        # ── Adobe Acrobat Reader ──────────────────────────────────────────────
        self.log("Installation d'Adobe Acrobat Reader...", "INFO")
        adobe = LOGICIELS["adobe"]
        if self._soft_present(adobe):
            self.log("Adobe déjà installé.", "SKIP")
        else:
            ok = self._winget_install(adobe["winget_id"], "Adobe Acrobat Reader")
            if ok and not self._soft_present(adobe):
                self.log("Adobe Reader — winget signale un succès mais rien d'installé.", "WARN")
                ok = False
            if not ok:
                # Repli : API Adobe (endpoint non documenté — traité comme fragile).
                self._install_adobe_direct()

        # ── Intel DSA ─────────────────────────────────────────────────────────
        self.log("Installation d'Intel Driver & Support Assistant...", "INFO")
        dsa = LOGICIELS["intel_dsa"]

        # Détection multicouche : exe, registre, service Windows
        def _dsa_detected() -> bool:
            return (
                any(Path(p).exists() for p in dsa["paths"])
                or is_installed_via_registry(dsa["reg_patterns"])
                or is_service_installed(dsa["service_name"])
            )

        if _dsa_detected():
            self.log("Intel DSA déjà installé.", "SKIP")
        elif dsa.get("winget_id") and self._winget_install(
                dsa["winget_id"], "Intel DSA") and _dsa_detected():
            # Méthode 1 : winget — paquet versionné et signé, sans dépendre d'une
            # URL « toujours le dernier » dont la forme n'est pas garantie.
            self.log("Intel DSA installé via winget.", "OK")
        else:
            # Méthode 2 : téléchargement direct sur dsadata.intel.com/installer
            # (urllib suit la redirection), puis exécution avec -s -norestart.
            if dsa.get("winget_id"):
                self.log("Intel DSA — repli sur le téléchargement direct.", "INFO")
            tmp = Path(tempfile.gettempdir()) / "Intel-DSA-Installer.exe"
            try:
                self.log("Téléchargement Intel DSA...", "CMD")
                req = urllib.request.Request(
                    dsa["dl_url"], headers={"User-Agent": "Mozilla/5.0"}
                )
                with urllib.request.urlopen(req, timeout=120) as resp:
                    tmp.write_bytes(resp.read())

                file_size = tmp.stat().st_size
                if file_size < 100 * 1024:
                    self.log(f"Intel DSA — fichier trop petit ({file_size} o), annulé.", "WARN")
                    self.log(f"Installez manuellement : {dsa['dl_url_fallback']}", "WARN")
                else:
                    # SEC-2 — vérification Authenticode avant exécution
                    sig_ok, sig_msg = verify_authenticode(tmp)
                    if not sig_ok:
                        # Signature invalide : on IGNORE uniquement Intel DSA, sans
                        # interrompre le reste de l'étape 6 (NVIDIA, NVIDIA App,
                        # Lenovo Vantage sont appelés APRÈS). L'ancien `return`
                        # tuait toute l'étape et sautait la détection NVIDIA.
                        self.log(f"Intel DSA — signature invalide : {sig_msg} — installation ignorée.", "FAIL")
                    else:
                        self.log(f"Intel DSA — {sig_msg}", "OK")
                        self.log("Installation Intel DSA (1-2 min)...", "CMD")
                        # Le code retour était ignoré : un refus des switches, un
                        # blocage GPO ou une exigence de redémarrage passaient donc
                        # inaperçus et ressortaient en simple « peut se terminer en
                        # arrière-plan ». On le lit et on le journalise.
                        code_dsa, out_dsa = run_cmd(
                            [str(tmp)] + dsa["dl_args"], timeout=300
                        )
                        DSA_OK_CODES = (0, 3010, 1641)
                        if code_dsa not in DSA_OK_CODES:
                            self.log(
                                f"Intel DSA — installeur terminé avec le code "
                                f"{code_dsa}.", "WARN"
                            )
                            for line in (out_dsa or "").strip().splitlines()[:5]:
                                if line.strip():
                                    self.log(f"  DSA: {line.strip()}", "CMD")
                        # Le service s'enregistre en arrière-plan. L'installeur
                        # annonce 1-2 min : on attend donc jusqu'à 2 min (au lieu
                        # de 30 s), ce qui évitait de conclure à un échec alors que
                        # l'installation aboutissait juste après.
                        for _ in range(24):
                            if _dsa_detected():
                                break
                            time.sleep(5)
                        if _dsa_detected():
                            self.log("Intel DSA installé avec succès.", "OK")
                        elif code_dsa in DSA_OK_CODES:
                            self.log(
                                "Intel DSA — installeur sorti sans erreur mais "
                                "service absent après 2 min ; peut se terminer "
                                "en arrière-plan.", "WARN"
                            )
                        else:
                            self.log(
                                f"Intel DSA — échec de l'installation "
                                f"(code {code_dsa}).", "FAIL"
                            )
                            self.log(
                                f"Installez manuellement : {dsa['dl_url_fallback']}",
                                "WARN"
                            )
            except Exception as exc:
                self.log(f"Intel DSA — erreur : {exc}", "FAIL")
                self.log(f"Installez manuellement : {dsa['dl_url_fallback']}", "WARN")
            finally:
                try:
                    tmp.unlink(missing_ok=True)
                except Exception:
                    pass

        # ── Pilote NVIDIA + NVIDIA App Entreprise (si GPU détecté) ─────────────
        self._install_nvidia_driver()
        self._install_nvidia_app()

        # ── Lenovo Commercial Vantage (matériel Lenovo) ────────────────────────
        self._install_commercial_vantage()

        self.step(6, "done", "Logiciels installés")
        self.progress(7, "Étape 7/11 — Favoris navigateurs")

    @staticmethod
    def _ps_encoded(script: str) -> list[str]:
        """Encode un script PS en base64 UTF-16LE et retourne les args powershell.
        Contourne le problème d'interprétation des $ et caractères spéciaux
        quand le script est passé via subprocess en argument -Command.

        On préfixe $ProgressPreference='SilentlyContinue' : sinon, au PREMIER appel
        d'une cmdlet CIM, PowerShell émet un flux de progression (« Préparation des
        modules à la première utilisation ») qui est capturé avec la sortie et
        pollue les valeurs lues (ex. le nom du GPU revenait en charabia).
        """
        script = "$ProgressPreference='SilentlyContinue'\n" + script
        encoded = base64.b64encode(script.encode("utf-16-le")).decode("ascii")
        return ["powershell", "-NoProfile", "-EncodedCommand", encoded]

    def _nvidia_device_id(self):
        """Retourne le Device ID (DEV_XXXX) du GPU NVIDIA, ou None si absent.

        CLÉ DE DÉTECTION = VEN_10DE (ID fabricant PCI de NVIDIA), présent dans le
        hardware ID QUEL QUE SOIT l'état du pilote. Indispensable en provisioning :
        sur une image fraîche, le GPU discret apparaît comme « 3D Video Controller »
        (Name SANS « NVIDIA ») tant que le pilote n'est pas installé — un filtre sur
        le nom échoue donc systématiquement à cette étape.

        On écarte les périphériques compagnons NVIDIA (audio HDMI, USB-C, HID,
        composant logiciel) qui portent aussi VEN_10DE, via l'exclusion des classes
        MEDIA/AudioEndpoint/USB/HIDClass/SoftwareComponent et la priorité à la classe
        Display / aux noms 3D/Display/VGA. Script encodé base64 (-EncodedCommand).
        """
        ps = (
            "$gpu = $null\n"
            "$gpu = Get-CimInstance Win32_VideoController -ErrorAction SilentlyContinue |"
            " Where-Object { $_.PNPDeviceID -like '*VEN_10DE*' } |"
            " Select-Object -First 1 -ExpandProperty PNPDeviceID\n"
            "if (-not $gpu) {\n"
            "    $gpu = Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue |"
            " Where-Object {\n"
            "        $_.DeviceID -like '*VEN_10DE*' -and $_.DeviceID -like '*DEV_*' -and\n"
            "        $_.PNPClass -ne 'MEDIA' -and $_.PNPClass -ne 'AudioEndpoint' -and\n"
            "        $_.PNPClass -ne 'USB' -and $_.PNPClass -ne 'HIDClass' -and\n"
            "        $_.PNPClass -ne 'SoftwareComponent'\n"
            "    } |\n"
            "    Sort-Object -Property @{ Expression = {\n"
            "        if ($_.PNPClass -eq 'Display') { 0 }\n"
            "        elseif ($_.Name -like '*3D*' -or $_.Name -like '*Display*' -or\n"
            "                $_.Name -like '*VGA*' -or $_.Name -like '*NVIDIA*') { 1 }\n"
            "        else { 2 } } } |\n"
            "    Select-Object -First 1 -ExpandProperty DeviceID\n"
            "}\n"
            "if ($gpu) { $gpu }\n"
        )
        code, out = run_cmd(self._ps_encoded(ps), timeout=30)
        # On ne bloque pas sur code != 0 : si l'ID est dans la sortie, on le prend.
        m = re.search(r"(DEV_[0-9A-F]{4})", (out or "").upper())
        return m.group(1) if m else None

    def _nvidia_gpu_name(self):
        """Retourne le nom du GPU NVIDIA, ou None si absent.

        Source 1 : nvidia-smi (nom exact si un pilote est installé).
        Source 2 : CIM sur VEN_10DE. ATTENTION — sur les GPU Ada laptop, le champ
        Name de CIM est souvent VIDE ; dans ce cas on renvoie None et l'appelant
        retombe sur NVIDIA_DEV_NAMES. Script encodé base64 (-EncodedCommand).
        """
        # Source 1 — nvidia-smi (le plus fiable quand un pilote est présent).
        smi = Path(os.environ.get("SystemRoot", r"C:\Windows")) / "System32" / "nvidia-smi.exe"
        code_smi, out_smi = run_cmd(
            [str(smi) if smi.exists() else "nvidia-smi",
             "--query-gpu=name", "--format=csv,noheader"],
            timeout=30
        )
        if code_smi == 0:
            first = (out_smi or "").strip().splitlines()[0].strip() if (out_smi or "").strip() else ""
            if first and "NVIDIA" in first.upper():
                return first

        # Source 2 — CIM (peut renvoyer un Name vide sur Ada laptop → None).
        ps = (
            "$name = $null\n"
            "$name = Get-CimInstance Win32_VideoController -ErrorAction SilentlyContinue |"
            " Where-Object { $_.PNPDeviceID -like '*VEN_10DE*' } |"
            " Select-Object -First 1 -ExpandProperty Name\n"
            "if (-not $name) {\n"
            "    $name = Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue |"
            " Where-Object {\n"
            "        $_.DeviceID -like '*VEN_10DE*' -and $_.DeviceID -like '*DEV_*' -and\n"
            "        $_.PNPClass -ne 'MEDIA' -and $_.PNPClass -ne 'AudioEndpoint' -and\n"
            "        $_.PNPClass -ne 'USB' -and $_.PNPClass -ne 'HIDClass' -and\n"
            "        $_.PNPClass -ne 'SoftwareComponent'\n"
            "    } |\n"
            "    Sort-Object -Property @{ Expression = {\n"
            "        if ($_.PNPClass -eq 'Display') { 0 }\n"
            "        elseif ($_.Name -like '*NVIDIA*') { 1 } else { 2 } } } |\n"
            "    Select-Object -First 1 -ExpandProperty Name\n"
            "}\n"
            # Émettre derrière une sentinelle ; n'accepter que si ça ressemble à un
            # vrai nom NVIDIA (pas 'Display', pas vide) — sinon l'appelant utilise
            # la table NVIDIA_DEV_NAMES.
            "if ($name -and $name -like '*NVIDIA*') { Write-Output ('NVGPUNAME=' + $name) }\n"
        )
        code, out = run_cmd(self._ps_encoded(ps), timeout=30)
        m = re.search(r"NVGPUNAME=(.+)", out or "")
        return m.group(1).strip() if m else None

    def _install_nvidia_driver(self):
        """Détecte un GPU NVIDIA et installe le dernier pilote via l'API NVIDIA.

        Port de la logique du script PowerShell d'origine :
        - Détection GPU + Device ID via CIM (Win32_PnPEntity / Win32_PnPSignedDriver)
        - Mapping Device ID → psid/pfid (fallback GeForce RTX générique 127/938)
        - Lookup NVIDIA AjaxDriverService → version + URL de téléchargement
        - Skip si le pilote installé est déjà à jour
        - Installation silencieuse (-s -noreboot -clean)
        Le CDN NVIDIA n'utilise pas le certificate pinning de winget : pas de 0x8A15005E ici.
        """
        self.log("PILOTE NVIDIA", "SECTION")

        # 1. Détecter un GPU NVIDIA et récupérer son Device ID via CIM.
        device_id = self._nvidia_device_id()
        if not device_id:
            # Diagnostic : lister TOUT périphérique PCI VEN_10DE présent, pour
            # distinguer « aucune carte NVIDIA » d'un problème de filtre.
            diag_ps = (
                "Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue |"
                " Where-Object { $_.DeviceID -like '*VEN_10DE*' } |"
                " ForEach-Object { \"  [$($_.PNPClass)] $($_.Name) :: $($_.DeviceID)\" }"
            )
            _, diag = run_cmd(self._ps_encoded(diag_ps), timeout=30)
            diag = (diag or "").strip()
            if diag:
                self.log(
                    "GPU NVIDIA non retenu par le filtre. Périphériques VEN_10DE "
                    "présents :\n" + diag, "WARN"
                )
            else:
                self.log(
                    "Aucun périphérique PCI NVIDIA (VEN_10DE) sur cette machine — "
                    "graphiques intégrés uniquement.", "INFO"
                )
            self.log("Aucun GPU NVIDIA détecté — étape ignorée.", "SKIP")
            return

        # 1b. Choisir la bonne branche de pilote selon le type de carte.
        #     - Pro/Workstation (Quadro, RTX A*, RTX Ada pro, RTX PRO Blackwell,
        #       série T) → pilote unifié RTX Enterprise (certifié ISV).
        #     - GeForce grand public → pilote GeForce (table ou fallback générique).
        name = self._nvidia_gpu_name() or ""
        # Un nom générique (« Display »…) n'identifie pas la carte : on lui
        # substitue le nom commercial issu du Device ID.
        if not name or name.strip().upper() in NVIDIA_GENERIC_NAMES:
            name = NVIDIA_DEV_NAMES.get(device_id, name)
        name_u = name.upper()
        is_workstation = (
            device_id in NVIDIA_PRO_LAPTOP_DEVICES
            or "QUADRO" in name_u
            or "RTX PRO" in name_u
            or ("ADA GENERATION" in name_u and "GEFORCE" not in name_u)
            or re.search(r"RTX A\d", name_u) is not None
            or re.search(r"\bT(400|600|1000|2000)\b", name_u) is not None
        )

        if is_workstation:
            psid, pfid = NVIDIA_ENTERPRISE_PSID, NVIDIA_ENTERPRISE_PFID
            branch = "RTX Enterprise"
            self.log(
                f"GPU Pro/Workstation détecté : {name or device_id} → "
                "pilote RTX Enterprise (certifié ISV).", "OK"
            )
        elif device_id in NVIDIA_GPU_TABLE:
            psid, pfid = NVIDIA_GPU_TABLE[device_id]
            branch = "GeForce"
            self.log(
                f"GPU GeForce détecté — {device_id} (psid={psid}/pfid={pfid}).",
                "OK"
            )
        else:
            psid, pfid = NVIDIA_FALLBACK_PSID, NVIDIA_FALLBACK_PFID
            branch = "GeForce"
            self.log(
                f"GPU GeForce détecté ({name or device_id}) — "
                "mapping GeForce RTX générique.", "WARN"
            )

        # 3. Version du pilote NVIDIA actuellement installé (format NVIDIA, ex. 576.02).
        installed = None
        # 3a. Source la plus fiable : nvidia-smi (présent dès qu'un pilote est
        #     installé) — donne DIRECTEMENT la version NVIDIA, sans conversion.
        smi = Path(os.environ.get("SystemRoot", r"C:\Windows")) / "System32" / "nvidia-smi.exe"
        code_smi, out_smi = run_cmd(
            [str(smi) if smi.exists() else "nvidia-smi",
             "--query-gpu=driver_version", "--format=csv,noheader"],
            timeout=30
        )
        msmi = re.search(r"(\d{3})\.(\d{2})", out_smi or "")
        if code_smi == 0 and msmi:
            installed = f"{msmi.group(1)}.{msmi.group(2)}"
        # 3b. Fallback CIM : DriverVersion Windows du GPU, filtré sur VEN_10DE
        #     et NON sur le nom — sur beaucoup de portables le DeviceName vaut
        #     littéralement « Display », donc l'ancien filtre `DeviceName -like
        #     '*nvidia*'` ne matchait jamais → « inconnu ».
        #     Conversion : les 5 DERNIERS chiffres de la queue → XXX.XX
        #     (ex. Windows 32.0.15.7602 → NVIDIA 576.02).
        if installed is None:
            _, out_v = run_cmd(self._ps_encoded(
                "$v = Get-CimInstance Win32_PnPSignedDriver -ErrorAction SilentlyContinue |"
                " Where-Object { $_.DeviceID -like '*VEN_10DE*' -and $_.DriverVersion } |"
                " Select-Object -First 1 -ExpandProperty DriverVersion\n"
                "if (-not $v) {\n"
                "    $v = Get-CimInstance Win32_VideoController -ErrorAction SilentlyContinue |"
                " Where-Object { $_.PNPDeviceID -like '*VEN_10DE*' } |"
                " Select-Object -First 1 -ExpandProperty DriverVersion\n"
                "}\n"
                "if ($v) { Write-Output ('NVDRV=' + $v) }\n"
            ), timeout=30)
            mver = re.search(r"NVDRV=([\d.]+)", out_v or "")
            if mver:
                digits = re.sub(r"\D", "", mver.group(1))
                if len(digits) >= 5:
                    last5 = digits[-5:]
                    installed = last5[:3] + "." + last5[3:]
        self.log(f"Pilote installé : {installed or 'inconnu'}", "INFO")

        # 4. Lookup NVIDIA : dernière version + URL de téléchargement.
        api = (
            "https://gfwsl.geforce.com/services_toolkit/services/com/nvidia/"
            "services/AjaxDriverService.php?func=DriverManualLookup"
            f"&psid={psid}&pfid={pfid}&osID=57"
            "&languageCode=1033&beta=null&isWHQL=1&dltype=-1&dch=1&upCRD=0"
        )
        try:
            req = urllib.request.Request(api, headers={"User-Agent": "Mozilla/5.0"})
            with urllib.request.urlopen(req, timeout=30) as resp:
                data = json.loads(resp.read().decode("utf-8", "replace"))
            info = data["IDS"][0]["downloadInfo"]
            latest = info.get("Version")
            dl_url = info.get("DownloadURL")
        except Exception as exc:
            self.log(f"NVIDIA — lookup API échoué : {exc}", "WARN")
            self.log("Téléchargez manuellement : "
                     "https://www.nvidia.com/Download/index.aspx", "WARN")
            return

        if not dl_url:
            self.log("NVIDIA — aucune URL de pilote retournée.", "WARN")
            return
        self.log(f"Dernier pilote {branch} disponible : {latest}", "INFO")

        # 5. Skip téléchargement si pilote déjà à jour — on continue quand même
        #    pour que _install_nvidia_app() soit toujours exécutée ensuite.
        if installed and latest and installed == latest:
            self.log("Pilote NVIDIA déjà à jour — téléchargement ignoré.", "SKIP")
            return  # retour dans _install_nvidia_driver() seulement ;
                    # _install_nvidia_app() est appelé juste après dans step6_software.

        # 6. Télécharger (streaming — le paquet fait ~600 Mo à 1 Go) et installer.
        tmp = Path(tempfile.gettempdir()) / "NVIDIA-Driver.exe"
        try:
            self.log(f"Téléchargement du pilote {branch} {latest}...", "CMD")
            req2 = urllib.request.Request(dl_url, headers={"User-Agent": "Mozilla/5.0"})
            with urllib.request.urlopen(req2, timeout=1800) as resp2, \
                 open(tmp, "wb") as f:
                shutil.copyfileobj(resp2, f)
            size_mb = tmp.stat().st_size / (1024 * 1024)
            if size_mb < 50:
                self.log(f"NVIDIA — fichier trop petit ({size_mb:.0f} Mo), annulé.", "WARN")
                return
            # SEC-2 — vérification Authenticode avant exécution
            sig_ok, sig_msg = verify_authenticode(tmp)
            if sig_ok:
                self.log(f"NVIDIA Driver — {sig_msg}", "OK")
            else:
                self.log(f"NVIDIA Driver — signature invalide : {sig_msg} — installation annulée.", "FAIL")
                return
            self.log(
                f"Installation silencieuse du pilote ({size_mb:.0f} Mo) — "
                "5 à 10 min, aucune nouvelle ligne pendant l'installation "
                "(l'écran peut clignoter, c'est normal)...", "CMD"
            )
            code_i, _ = run_cmd(
                [str(tmp), "-s", "-noreboot", "-clean"], timeout=1800
            )
            if code_i in (0, 1):
                self.log(f"Pilote {branch} {latest} installé.", "OK")
            else:
                self.log(
                    f"NVIDIA — installeur code {code_i} "
                    "(vérification manuelle recommandée).", "WARN"
                )
        except Exception as exc:
            self.log(f"NVIDIA — erreur : {exc}", "FAIL")
        finally:
            try:
                tmp.unlink(missing_ok=True)
            except Exception:
                pass

    def _install_nvidia_app(self):
        """Installe l'application NVIDIA — édition Entreprise/Workstation (cartes Pro).

        Compagnon des pilotes RTX Enterprise : centre de contrôle GPU unifié,
        recommandations de pilotes, capture, monitoring. Ne s'exécute que si un
        GPU NVIDIA est présent. URL résolue dynamiquement depuis la page NVIDIA,
        avec repli sur la version connue. Install silencieuse.
        """
        # Ne rien faire sans GPU NVIDIA.
        if not self._nvidia_device_id():
            return

        self.log("NVIDIA APP (Entreprise)", "SECTION")

        # Skip si déjà installée.
        app_paths = [
            r"C:\Program Files\NVIDIA Corporation\NVIDIA app\CEF\NVIDIA app.exe",
            r"C:\Program Files\NVIDIA Corporation\NVIDIA App\CEF\NVIDIA App.exe",
        ]
        if any(Path(p).exists() for p in app_paths):
            self.log("NVIDIA App déjà installée.", "SKIP")
            return

        # 1. Résoudre l'URL du dernier installeur depuis la page NVIDIA Entreprise.
        page = "https://www.nvidia.com/en-us/software/nvidia-app-enterprise/"
        fallback_url = (
            "https://us.download.nvidia.com/nvapp/client/"
            "11.0.7.247/NVIDIA_app_v11.0.7.247.exe"
        )
        dl_url = None
        try:
            req = urllib.request.Request(page, headers={"User-Agent": "Mozilla/5.0"})
            with urllib.request.urlopen(req, timeout=30) as resp:
                html = resp.read().decode("utf-8", "replace")
            m = re.search(
                r"https://us\.download\.nvidia\.com/nvapp/client/"
                r"[\d.]+/NVIDIA_app_v[\d.]+\.exe",
                html
            )
            if m:
                dl_url = m.group(0)
        except Exception as exc:
            self.log(f"NVIDIA App — résolution URL échouée : {exc}", "WARN")
        if not dl_url:
            dl_url = fallback_url
            self.log("NVIDIA App — URL de repli utilisée.", "WARN")
        self.log(f"NVIDIA App — installeur : {dl_url.rsplit('/', 1)[-1]}", "CMD")

        # 2. Télécharger (~150 Mo) et installer en silencieux.
        tmp = Path(tempfile.gettempdir()) / "NVIDIA_app.exe"
        try:
            req2 = urllib.request.Request(dl_url, headers={"User-Agent": "Mozilla/5.0"})
            with urllib.request.urlopen(req2, timeout=600) as resp2, \
                 open(tmp, "wb") as f:
                shutil.copyfileobj(resp2, f)
            size_mb = tmp.stat().st_size / (1024 * 1024)
            if size_mb < 20:
                self.log(f"NVIDIA App — fichier trop petit ({size_mb:.0f} Mo), annulé.", "WARN")
                return
            # SEC-2 — vérification Authenticode avant exécution
            sig_ok, sig_msg = verify_authenticode(tmp)
            if sig_ok:
                self.log(f"NVIDIA App — {sig_msg}", "OK")
            else:
                self.log(f"NVIDIA App — signature invalide : {sig_msg} — installation annulée.", "FAIL")
                return
            self.log(f"Installation silencieuse de NVIDIA App ({size_mb:.0f} Mo)...", "CMD")
            code_i, _ = run_cmd(
                [str(tmp), "-silent", "-noreboot", "-noeula", "-nofinish", "-passive"],
                timeout=600
            )
            if code_i in (0, 1):
                self.log("NVIDIA App (Entreprise) installée.", "OK")
            else:
                self.log(
                    f"NVIDIA App — installeur code {code_i} "
                    "(vérification manuelle recommandée).", "WARN"
                )
        except Exception as exc:
            self.log(f"NVIDIA App — erreur : {exc}", "FAIL")
        finally:
            try:
                tmp.unlink(missing_ok=True)
            except Exception:
                pass

    def _install_commercial_vantage(self):
        """Installe Lenovo Commercial Vantage (paquet de déploiement entreprise).

        Utilise VantageInstaller.exe du paquet Lenovo (fichier compagnon), PAS le
        Microsoft Store — on évite ainsi le 0x8A15005E. Uniquement sur matériel
        Lenovo. Paramètres VantageInstaller SENSIBLES À LA CASSE.
        """
        # 1. Confirmer que c'est bien un poste Lenovo.
        _, out_m = run_cmd(
            ["powershell", "-NoProfile", "-Command",
             "(Get-CimInstance Win32_ComputerSystem).Manufacturer"], timeout=20
        )
        if "LENOVO" not in (out_m or "").upper():
            self.log("Poste non-Lenovo — Commercial Vantage ignoré.", "SKIP")
            return

        self.log("LENOVO COMMERCIAL VANTAGE", "SECTION")

        # 2. Déjà installé ? (paquet appx provisionné E046963F.LenovoSettingsforEnterprise)
        _check = (
            "if (Get-AppxPackage -AllUsers *LenovoSettingsforEnterprise* "
            "-ErrorAction SilentlyContinue) { 'YES' } else { 'NO' }"
        )
        _, out_c = run_cmd(
            ["powershell", "-NoProfile", "-Command", _check], timeout=30
        )
        if "YES" in (out_c or "").upper():
            self.log("Commercial Vantage déjà installé.", "SKIP")
            return

        # 3. Localiser VantageInstaller.exe (paquet de déploiement Lenovo EXTRAIT).
        cands = [LGS_DEPLOY_DIR / "CommercialVantage" / "VantageInstaller.exe"]
        try:
            script_dir = Path(os.path.abspath(sys.argv[0])).parent
            cands += [script_dir / "VantageInstaller.exe",
                      script_dir / "CommercialVantage" / "VantageInstaller.exe"]
        except Exception:
            pass
        cands += [Path(r"C:\Vantage\VantageInstaller.exe"),
                  Path(r"C:\Deploy\CommercialVantage\VantageInstaller.exe")]
        installer = next((c for c in cands if c.exists()), None)
        if installer is None:
            # Erreur classique : le ZIP Lenovo est déposé sans être extrait.
            # Le signaler explicitement plutôt que « fichier introuvable ».
            zips = []
            for d in (LGS_DEPLOY_DIR / "CommercialVantage", LGS_DEPLOY_DIR):
                try:
                    if d.is_dir():
                        zips += [z for z in d.glob("*.zip")]
                except Exception:
                    pass
            if zips:
                self.log(
                    f"Archive Lenovo trouvée mais NON EXTRAITE : {zips[0].name}. "
                    "Extrayez-la sur place pour que VantageInstaller.exe soit "
                    "accessible, puis relancez.", "WARN"
                )
                return
            # Repli Microsoft Store. ATTENTION : 9NR5B8GVVM13 est bien la version
            # COMMERCIALE (9WZDNCRFJ4MV est la version grand public, à proscrire
            # sur un poste corpo). Ce repli n'installe toutefois QUE l'application :
            # le paquet de déploiement, lui, pose aussi le System Update Helper
            # (VantageInstaller Install -Vantage -SuHelper). Il reste donc la
            # méthode de référence.
            if self._msstore_install(self.VANTAGE_STORE_ID, "Commercial Vantage"):
                _, out_s = run_cmd(
                    ["powershell", "-NoProfile", "-Command", _check], timeout=30
                )
                if "YES" in (out_s or "").upper():
                    self.log(
                        "Commercial Vantage installé depuis le Microsoft Store. "
                        "Note : le System Update Helper n'est PAS inclus — "
                        "déployez le paquet Lenovo pour une installation complète.",
                        "WARN"
                    )
                    return
                self.log("Commercial Vantage — Store : app non détectée après installation.", "WARN")

            # Créer le dossier attendu : plus clair pour l'opérateur qu'un chemin
            # mentionné dans un message mais inexistant sur le disque.
            target = LGS_DEPLOY_DIR / "CommercialVantage"
            try:
                target.mkdir(parents=True, exist_ok=True)
            except Exception:
                pass
            self.log(
                "VantageInstaller.exe introuvable. Déposez le paquet de "
                "déploiement Lenovo Commercial Vantage (EXTRAIT) dans "
                f"{target}\\, puis relancez. "
                "Paquet : https://docs.lenovocdrt.com/guides/lcv/", "WARN"
            )
            return
        self.log(f"VantageInstaller trouvé : {installer}", "OK")

        # 4. Installation complète : App + Service + SU Helper.
        self.log("Installation de Commercial Vantage...", "CMD")
        code_i, _ = run_cmd(
            [str(installer), "Install", "-Vantage", "-SuHelper"], timeout=900
        )
        # VantageInstaller lance un helper asynchrone : attendre sa fin.
        run_cmd(
            ["powershell", "-NoProfile", "-Command",
             "$p = Get-Process -Name 'Lenovo.Vantage.InstallerHelper' "
             "-ErrorAction SilentlyContinue; "
             "if ($p) { Wait-Process -Id $p.Id -Timeout 600 }"],
            timeout=650
        )

        # 5. Vérifier.
        _, out_v = run_cmd(
            ["powershell", "-NoProfile", "-Command", _check], timeout=30
        )
        if "YES" in (out_v or "").upper():
            self.log("Commercial Vantage installé.", "OK")
        else:
            self.log(
                f"Commercial Vantage — installeur code {code_i} ; app non "
                "détectée (peut se finaliser en arrière-plan).", "WARN"
            )

    def _install_adobe_direct(self):
        """Méthode de secours : téléchargement direct via l'API Adobe."""
        try:
            self.log("Adobe — méthode directe : API Adobe...", "CMD")
            api_url = "https://rdc.adobe.io/reader/products?os=windows&arch=x64&productType=dc"
            with urllib.request.urlopen(api_url, timeout=30) as resp:
                data = json.loads(resp.read())
            ver = data["products"][0]["version"]
            ver_flat = ver.replace(".", "")
            dl_url = (
                f"https://ardownload2.adobe.com/pub/adobe/reader/win/AcrobatDC/"
                f"{ver_flat}/AcroRdrDC{ver_flat}_en_US.exe"
            )
            tmp = Path(tempfile.gettempdir()) / f"AdobeReader_{ver_flat}.exe"
            self.log(f"Téléchargement Adobe Reader {ver}...", "CMD")
            # SEC-QUAL-6 : urlretrieve dépréciée remplacée par urlopen + copyfileobj
            req_adobe = urllib.request.Request(dl_url, headers={"User-Agent": "Mozilla/5.0"})
            with urllib.request.urlopen(req_adobe, timeout=300) as resp_adobe, \
                 open(tmp, "wb") as f_adobe:
                shutil.copyfileobj(resp_adobe, f_adobe)
            if tmp.stat().st_size > 100 * 1024 * 1024:
                # SEC-2 — vérification Authenticode avant exécution
                sig_ok, sig_msg = verify_authenticode(tmp)
                if sig_ok:
                    self.log(f"Adobe Reader — {sig_msg}", "OK")
                else:
                    self.log(f"Adobe Reader — signature invalide : {sig_msg} — installation annulée.", "FAIL")
                    tmp.unlink(missing_ok=True)
                    return
                run_cmd([str(tmp), "/sAll", "/rs", "/msi",
                         "EULA_ACCEPT=YES", "SUPPRESS_APP_LAUNCH=YES"])
                self.log(f"Adobe Reader {ver} installé.", "OK")
            else:
                self.log("Fichier Adobe trop petit — installation ignorée.", "WARN")
            tmp.unlink(missing_ok=True)
        except Exception as exc:
            self.log(f"Adobe direct — échec : {exc}", "FAIL")
            self.log("Installez Adobe manuellement : https://get.adobe.com/reader/", "WARN")

    # ─────────────────────────────────────────────────────────────────────────
    # ÉTAPE 7 — Favoris Edge
    # ─────────────────────────────────────────────────────────────────────────

    def step7_edge_bookmarks(self):
        self.step(7, "active", "Configuration des favoris...")
        self.log("FAVORIS NAVIGATEURS", "SECTION")

        # ── Edge (Chromium) ────────────────────────────────────────────────────
        self._write_chromium_bookmarks(
            os.path.expandvars(r"%LOCALAPPDATA%\Microsoft\Edge\User Data"),
            "msedge.exe", "Edge",
            (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Policies\Microsoft\Edge",
             "FavoritesBarEnabled"),
        )

        # ── Chrome (Chromium — même format que Edge) ───────────────────────────
        self._write_chromium_bookmarks(
            os.path.expandvars(r"%LOCALAPPDATA%\Google\Chrome\User Data"),
            "chrome.exe", "Chrome",
            (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Policies\Google\Chrome",
             "BookmarkBarEnabled"),
        )

        # ── Firefox (policies.json) ────────────────────────────────────────────
        self._write_firefox_bookmarks()

        self.step(7, "done", "Favoris navigateurs configurés")
        self.progress(8, "Étape 8/11 — Configuration Windows")

    def _write_chromium_bookmarks(self, user_data: str, proc_name: str,
                                  label: str, bar_reg: tuple):
        """Écrit BOOKMARKS_JSON dans tous les profils d'un navigateur Chromium
        (Edge ou Chrome — format identique) et active la barre des favoris (GPO).
        Chrome et Edge partagent exactement le même fichier « Bookmarks »."""
        self.log(f"Favoris {label}...", "CMD")
        run_cmd(["taskkill", "/F", "/IM", proc_name], capture=True)
        time.sleep(1)

        base = Path(user_data)
        written = 0
        if base.exists():
            profiles = ["Default"] + [
                d.name for d in base.iterdir()
                if d.is_dir() and re.match(r"^Profile \d+$", d.name)
            ]
            for profile in profiles:
                pp = base / profile
                if pp.exists():
                    try:
                        (pp / "Bookmarks").write_text(BOOKMARKS_JSON, encoding="utf-8")
                        (pp / "Bookmarks.bak").unlink(missing_ok=True)
                        self.log(f"{label} — favoris écrits : profil '{profile}'", "OK")
                        written += 1
                    except Exception as exc:
                        self.log(f"{label} — '{profile}' : {exc}", "WARN")

        if written == 0:
            # Aucun profil : pré-créer Default (avant le 1er lancement du navigateur).
            default = base / "Default"
            try:
                default.mkdir(parents=True, exist_ok=True)
                (default / "Bookmarks").write_text(BOOKMARKS_JSON, encoding="utf-8")
                self.log(f"{label} — favoris écrits (nouveau profil Default).", "OK")
            except Exception as exc:
                self.log(f"{label} — création profil Default : {exc}", "WARN")

        # Activer la barre des favoris via GPO.
        try:
            hive, path, name = bar_reg
            reg_set(hive, path, name, 1, winreg.REG_DWORD)
            self.log(f"{label} — barre des favoris activée (GPO).", "OK")
        except Exception as exc:
            self.log(f"{label} — barre des favoris : {exc}", "WARN")

    def _write_firefox_bookmarks(self):
        """Génère policies.json (politique Bookmarks) à partir de BOOKMARKS_JSON
        et le dépose dans <Firefox>\\distribution\\. Réplique la vue Edge :
        dossier WebApps conservé + liens directs, tout sur la barre (toolbar).
        Fusionne avec un policies.json existant plutôt que de l'écraser."""
        self.log("Favoris Firefox (policies.json)...", "CMD")

        ff_dir = next(
            (d for d in (Path(r"C:\Program Files\Mozilla Firefox"),
                         Path(r"C:\Program Files (x86)\Mozilla Firefox"))
             if (d / "firefox.exe").exists()),
            None
        )
        if ff_dir is None:
            self.log("Firefox non installé — favoris ignorés.", "SKIP")
            return

        # Aplatir BOOKMARKS_JSON → liste de favoris (Placement=toolbar).
        try:
            bar = json.loads(BOOKMARKS_JSON)["roots"]["bookmark_bar"]["children"]
        except Exception as exc:
            self.log(f"Firefox — lecture des favoris échouée : {exc}", "WARN")
            return

        bookmarks = []

        def _walk(nodes, folder):
            for n in nodes:
                if n.get("type") == "url":
                    bm = {"Title": n.get("name", ""), "URL": n.get("url", ""),
                          "Placement": "toolbar"}
                    if folder:
                        bm["Folder"] = folder
                    bookmarks.append(bm)
                elif n.get("type") == "folder":
                    _walk(n.get("children", []), n.get("name") or folder)

        _walk(bar, None)

        # Fusionner avec un policies.json existant (préserve les autres politiques).
        dist = ff_dir / "distribution"
        pj = dist / "policies.json"
        merged = {}
        if pj.exists():
            try:
                merged = json.loads(pj.read_text(encoding="utf-8"))
            except Exception:
                merged = {}
        if not isinstance(merged, dict):
            merged = {}
        merged.setdefault("policies", {})
        merged["policies"]["DisplayBookmarksToolbar"] = "always"
        merged["policies"]["Bookmarks"] = bookmarks

        try:
            dist.mkdir(parents=True, exist_ok=True)
            pj.write_text(
                json.dumps(merged, ensure_ascii=False, indent=2), encoding="utf-8"
            )
            self.log(f"Firefox — {len(bookmarks)} favoris écrits (policies.json).", "OK")
        except Exception as exc:
            self.log(f"Firefox — écriture policies.json : {exc}", "WARN")

    # ─────────────────────────────────────────────────────────────────────────
    # ÉTAPE 8 — Configuration Windows
    # ─────────────────────────────────────────────────────────────────────────

    # ─────────────────────────────────────────────────────────────────────────
    # Écriture multi-ruches (partagée : écran de veille + configuration régionale)
    # ─────────────────────────────────────────────────────────────────────────

    # ATTENTION — le filtre ne peut pas se limiter à « S-1-5-21- » :
    #   S-1-5-21-…  comptes locaux et Active Directory
    #   S-1-12-1-…  comptes ENTRA ID (Azure AD)
    # Or ce script joint lui-même les postes à Entra ID : sur ces machines,
    # l'utilisateur final porte un SID S-1-12-1-… et n'était donc JAMAIS traité.
    # Les SID de services (S-1-5-18/19/20, S-1-5-80-…) et .DEFAULT sont
    # volontairement exclus : ce ne sont pas des sessions utilisateur.
    USER_SID_RE = re.compile(r"^S-1-(?:5-21|12-1)-[\d-]+$")

    @classmethod
    def _loaded_user_sids(cls) -> list:
        """SID des ruches utilisateur réelles actuellement chargées dans HKU."""
        sids, i = [], 0
        while True:
            try:
                sub = winreg.EnumKey(winreg.HKEY_USERS, i)
            except OSError:
                break
            i += 1
            if cls.USER_SID_RE.match(sub):
                sids.append(sub)
        return sids

    def _write_all_user_hives(self, subkey: str, values: dict, label: str) -> int:
        """Écrit `values` sous HKU\\<ruche>\\<subkey> pour TOUS les utilisateurs.

        Le script tourne élevé : HKEY_CURRENT_USER pointe vers la ruche de
        l'ADMIN, pas celle de l'utilisateur final. On écrit donc dans :
          - le profil par défaut (C:\\Users\\Default\\NTUSER.DAT) → tout nouvel
            utilisateur hérite du réglage dès sa 1re ouverture de session ;
          - chaque ruche utilisateur déjà chargée.

        Retourne le nombre de ruches effectivement écrites.
        """
        def _write(prefix: str) -> bool:
            ok = True
            for name, val in values.items():
                if not reg_set(winreg.HKEY_USERS, prefix + "\\" + subkey, name, val):
                    ok = False
            return ok

        applied = 0

        # 1. Profil par défaut : charger NTUSER.DAT, écrire, décharger.
        sysdrive = os.environ.get("SystemDrive", "C:")
        default_dat = Path(sysdrive + r"\Users\Default\NTUSER.DAT")
        if default_dat.exists():
            code, _ = run_cmd(
                ["reg", "load", r"HKU\INSTALLEX_DEFAULT", str(default_dat)], timeout=30
            )
            if code == 0:
                try:
                    if _write("INSTALLEX_DEFAULT"):
                        applied += 1
                        self.log(f"{label} — appliqué au profil par défaut.", "OK")
                except Exception as exc:
                    self.log(f"{label} (profil défaut) : {exc}", "WARN")
                finally:
                    run_cmd(["reg", "unload", r"HKU\INSTALLEX_DEFAULT"], timeout=30)
            else:
                self.log(f"{label} — profil par défaut non chargeable.", "WARN")

        # 2. Ruches utilisateur réelles déjà chargées.
        try:
            sids = self._loaded_user_sids()
            for sid in sids:
                if _write(sid):
                    applied += 1
                    self.log(f"{label} — ruche {sid}", "CMD")
            if sids:
                self.log(f"{label} — appliqué à {len(sids)} session(s) utilisateur.", "OK")
            else:
                self.log(
                    f"{label} — aucune ruche utilisateur chargée ; seul le profil "
                    "par défaut est configuré.", "WARN"
                )
        except Exception as exc:
            self.log(f"{label} (ruches chargées) : {exc}", "WARN")

        if applied == 0:
            self.log(f"{label} — aucune ruche cible trouvée.", "WARN")
        return applied

    def _configure_screensaver(self):
        """Configure l'écran de veille (Ribbons, 10 min, verrouillage) pour TOUS
        les utilisateurs — pas seulement le compte admin élevé."""
        timeout_s = int(CONFIG.get("screensaver_timeout") or 600)
        values = {
            "ScreenSaveActive":    "1",
            "SCRNSAVE.EXE":        r"C:\Windows\System32\Ribbons.scr",
            "ScreenSaveTimeOut":   str(timeout_s),   # 10 min par défaut
            "ScreenSaverIsSecure": "1",              # verrouillage à la reprise
        }
        applied = self._write_all_user_hives(
            r"Control Panel\Desktop", values, "Écran de veille"
        )
        if applied:
            self.log(
                f"Écran de veille : Ribbons.scr, {timeout_s // 60} min, "
                "verrouillage activé.", "OK"
            )

        # Appliquer à la session OUVERTE (voir _apply_screensaver_now).
        self._apply_screensaver_now(int(values["ScreenSaveTimeOut"]))

    # Fuseau des postes LGS (Québec). Nom d'ID Windows, invariant de la langue.
    # Surchargeable par la configuration externe (clé « timezone »).
    TIMEZONE_ID = CONFIG.get("timezone") or "Eastern Standard Time"
    GEO_ID_CANADA = 39          # Set-WinHomeLocation : code géographique Canada

    def _configure_regional(self):
        """Configuration régionale : fr-CA, date ISO (yyyy-MM-dd), horloge 24 h.

        Écrit dans « Control Panel\\International » de toutes les ruches (profil
        par défaut + sessions chargées) pour la même raison que l'écran de veille :
        en contexte élevé, HKCU est la ruche de l'admin, pas celle de l'utilisateur.

        Le fuseau horaire et la position géographique sont, eux, des réglages
        MACHINE : ils se posent une seule fois via tzutil / Set-WinHomeLocation.
        """
        self.log("CONFIGURATION RÉGIONALE", "SECTION")

        values = {
            "LocaleName":   CONFIG.get("locale") or "fr-CA",
            "sShortDate":   CONFIG.get("short_date") or "yyyy-MM-dd",  # ISO 8601
            "sLongDate":    "d MMMM yyyy",
            "sShortTime":   "HH:mm",          # 24 h
            "sTimeFormat":  "HH:mm:ss",
            "iTime":        "1",              # 1 = horloge 24 h
            "iTLZero":      "1",              # heure sur 2 chiffres (09:05)
            "sDate":        "-",              # séparateur de date ISO
            "sTime":        ":",
        }
        self._write_all_user_hives(
            r"Control Panel\International", values, "Configuration régionale"
        )

        # Fuseau horaire (machine).
        code_tz, out_tz = run_cmd(["tzutil", "/s", self.TIMEZONE_ID], timeout=20)
        if code_tz == 0:
            self.log(f"Fuseau horaire : {self.TIMEZONE_ID}.", "OK")
        else:
            self.log(
                f"Fuseau horaire — échec (code {code_tz}) : "
                f"{(out_tz or '').strip()[:120]}", "WARN"
            )

        # Position géographique (machine) — influence unités et formats régionaux.
        code_geo, _ = run_cmd(self._ps_encoded(
            f"Set-WinHomeLocation -GeoId {self.GEO_ID_CANADA} -ErrorAction Stop"
        ), timeout=30)
        if code_geo == 0:
            self.log("Position géographique : Canada.", "OK")
        else:
            self.log("Position géographique — non appliquée (non bloquant).", "WARN")

        self.log(
            "Régional : fr-CA, date yyyy-MM-dd, horloge 24 h "
            "(effectif à la prochaine ouverture de session).", "OK"
        )

    def _apply_screensaver_now(self, timeout_s: int = 600):
        """Applique l'écran de veille à la session en cours, sans attendre une
        réouverture de session.

        Écrire dans « Control Panel\\Desktop » ne suffit pas : Windows conserve
        les paramètres d'écran de veille en cache pour la session ouverte et ne
        relit le registre qu'à l'ouverture suivante. Sans cet appel, le réglage
        semblait ne « prendre » qu'après un redémarrage — l'écran de veille ne se
        déclenchait jamais pendant la session de provisionnement.

        SystemParametersInfoW avec SPIF_SENDCHANGE diffuse le changement aux
        fenêtres de la session, qui rechargent immédiatement le paramètre.
        Purement cosmétique pour la suite du script : un échec ici n'a aucun
        impact, le registre restant la source de vérité pour les sessions futures.
        """
        SPI_SETSCREENSAVETIMEOUT = 0x000F
        SPI_SETSCREENSAVEACTIVE  = 0x0011
        SPIF_UPDATEINIFILE       = 0x01
        SPIF_SENDCHANGE          = 0x02
        flags = SPIF_UPDATEINIFILE | SPIF_SENDCHANGE
        try:
            spi = ctypes.windll.user32.SystemParametersInfoW
            spi.restype = ctypes.c_bool
            spi.argtypes = [ctypes.c_uint, ctypes.c_uint,
                            ctypes.c_void_p, ctypes.c_uint]
            ok_timeout = spi(SPI_SETSCREENSAVETIMEOUT, timeout_s, None, flags)
            ok_active  = spi(SPI_SETSCREENSAVEACTIVE, 1, None, flags)
            if ok_timeout and ok_active:
                self.log(
                    f"Écran de veille actif immédiatement "
                    f"({timeout_s // 60} min) — sans redémarrage.", "OK"
                )
            else:
                self.log(
                    "Écran de veille — session en cours non notifiée ; le réglage "
                    "s'appliquera à la prochaine ouverture de session.", "WARN"
                )
        except Exception as exc:
            self.log(
                f"Écran de veille — notification de session impossible ({exc}) ; "
                "le réglage s'appliquera à la prochaine ouverture de session.", "WARN"
            )

    def step8_windows_config(self):
        self.step(8, "active", "Configuration en cours...")
        self.log("CONFIGURATION WINDOWS", "SECTION")

        # Écran de veille — appliqué à TOUS les utilisateurs (pas la ruche admin).
        self._configure_screensaver()

        # Configuration régionale : fr-CA, date ISO, horloge 24 h, fuseau.
        self._configure_regional()

        # Désactivation démarrage rapide
        try:
            reg_set(
                winreg.HKEY_LOCAL_MACHINE,
                r"SYSTEM\CurrentControlSet\Control\Session Manager\Power",
                "HiberbootEnabled", 0, winreg.REG_DWORD
            )
            self.log("Démarrage rapide désactivé.", "OK")
        except Exception as exc:
            self.log(f"Démarrage rapide — erreur : {exc}", "WARN")

        # Restauration veille : valeurs exactes sauvegardées au démarrage
        self._restore_power_settings()

        self.step(8, "done", "Configuration Windows terminée")
        self.progress(9, "Étape 9/11 — Windows Update")

    # ─────────────────────────────────────────────────────────────────────────
    # ÉTAPE 9 — Windows Update
    # ─────────────────────────────────────────────────────────────────────────

    # Budget de temps accordé à Windows Update, en secondes. Passé ce délai on
    # passe à l'étape suivante : les mises à jour restantes se poseront d'elles-
    # mêmes après la remise du poste, alors qu'un technicien immobilisé une ou
    # deux heures devant la barre de progression, non. Le budget couvre l'étape
    # ENTIÈRE : ce qui reste après PSWindowsUpdate est ce dont dispose le repli
    # WUA, pour que le total ne dérive pas.
    WU_BUDGET_S = 600   # 10 minutes

    def step9_windows_update(self):
        self.step(9, "active", "Recherche des mises à jour...")
        self.log("WINDOWS UPDATE", "SECTION")
        wu_debut = time.monotonic()

        # ── Redémarrage en attente : on le SIGNALE mais on tente quand même ───
        #
        # Historique : cette détection provoquait un `return` immédiat, donc un
        # abandon pur et simple de Windows Update. C'était contre-productif pour
        # deux raisons.
        #
        # 1) La condition est très largement AUTO-INFLIGÉE. L'étape 9 s'exécute
        #    après l'installation d'Office (étape 5), des logiciels et pilotes
        #    (étape 6) et de la configuration Windows (étape 8) — or ces
        #    installations posent précisément un redémarrage en attente. Le code
        #    accepte d'ailleurs 3010 comme succès, et 3010 signifie « succès,
        #    redémarrage requis ». Le script créait donc lui-même la condition
        #    qui le faisait renoncer, et Windows Update ne tournait quasiment
        #    jamais. (Mesuré sur un poste provisionné : 3 des 4 indicateurs
        #    étaient présents.)
        #
        # 2) La prémisse est trop stricte. Un redémarrage en attente ne bloque
        #    pas Windows Update en général — seulement certaines opérations de
        #    servicing. PendingFileRenameOperations en particulier est posé par
        #    quasiment tous les installeurs et ne bloque pratiquement jamais.
        #
        # On journalise donc l'état, on mémorise le besoin de redémarrage pour le
        # bilan final, et on TENTE la mise à jour. Si Windows la refuse vraiment,
        # le traitement d'erreur plus bas (PSWU_FAIL contenant « reboot » /
        # « restart » / « pending ») intercepte le cas et sort proprement : au
        # pire on retombe sur le comportement précédent, après un essai.
        reboot_pending_keys = [
            (winreg.HKEY_LOCAL_MACHINE,
             r"SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired"),
            (winreg.HKEY_LOCAL_MACHINE,
             r"SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending"),
            (winreg.HKEY_LOCAL_MACHINE,
             r"SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\PackagesPending"),
            (winreg.HKEY_LOCAL_MACHINE,
             r"SYSTEM\CurrentControlSet\Control\Session Manager"),  # PendingFileRenameOperations
        ]
        reboot_required = False
        for hive, path in reboot_pending_keys[:3]:  # les 3 premières sont booléennes (clé présente = reboot)
            try:
                with winreg.OpenKey(hive, path):
                    reboot_required = True
                    break
            except OSError:
                continue

        # Cas spécial : PendingFileRenameOperations dans Session Manager
        if not reboot_required:
            try:
                with winreg.OpenKey(
                    winreg.HKEY_LOCAL_MACHINE,
                    r"SYSTEM\CurrentControlSet\Control\Session Manager"
                ) as key:
                    val, _ = winreg.QueryValueEx(key, "PendingFileRenameOperations")
                    if val:
                        reboot_required = True
            except OSError:
                pass

        if reboot_required:
            # Mémorisé pour le bilan final (_check_reboot_required), qui
            # annonçait « aucun redémarrage nécessaire » malgré ce constat.
            self._reboot_pending_seen = True
            self.log(
                "Redémarrage en attente détecté (probablement dû aux installations "
                "des étapes précédentes). Windows Update est tenté malgré tout.", "WARN"
            )

        # Méthode 1 : PSWindowsUpdate via PowerShell (UTF-8 forcé via chcp)
        ps_script = r"""
$OutputEncoding = [System.Text.Encoding]::UTF8
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$ErrorActionPreference = 'Stop'
$prevPolicy = $null
try {
    Install-PackageProvider -Name NuGet -MinimumVersion 2.8.5.201 -Force -Scope AllUsers -EA SilentlyContinue | Out-Null
    # Mémoriser la politique PSGallery : le poste livré ne doit pas rester avec
    # un dépôt marqué Trusted (elle est restaurée dans le finally).
    $prevPolicy = (Get-PSRepository -Name PSGallery -EA SilentlyContinue).InstallationPolicy
    if (-not (Get-Module -ListAvailable -Name PSWindowsUpdate)) {
        Set-PSRepository -Name PSGallery -InstallationPolicy Trusted -EA SilentlyContinue
        Install-Module -Name PSWindowsUpdate -Force -Scope AllUsers -AllowClobber -Repository PSGallery -EA Stop | Out-Null
    }
    Import-Module PSWindowsUpdate -Force -EA Stop

    # Enregistrer le service Microsoft Update : apporte les correctifs Office et
    # les pilotes, absents du service Windows Update seul.
    try {
        $sm = New-Object -ComObject Microsoft.Update.ServiceManager
        $sm.AddService2('7971f918-a847-4430-9279-4a52d1efe18d', 7, '') | Out-Null
        Write-Host "INFO: Service Microsoft Update enregistre (Office + pilotes)"
    } catch {
        Write-Host "INFO: Microsoft Update non enregistre - $($_.Exception.Message)"
    }

    # Boucle multi-passes : Windows Update revele souvent de nouvelles MAJ une
    # fois les precedentes posees. On s'arrete des qu'il n'y a plus rien, qu'un
    # redemarrage est requis, ou au bout de 3 passes.
    $total = 0
    for ($pass = 1; $pass -le 3; $pass++) {
        # UNE seule commande recherche ET installe (-Install) : l'ancien code
        # enchainait Get-WindowsUpdate puis Install-WindowsUpdate, soit deux
        # balayages complets de Windows Update.
        $res = @(Get-WindowsUpdate -MicrosoftUpdate -AcceptAll -Install -IgnoreReboot -EA Stop)
        if ($res.Count -eq 0) {
            if ($pass -eq 1) { Write-Host "DONE: Systeme deja a jour" }
            else { Write-Host "DONE: $total mise(s) a jour installee(s)" }
            break
        }
        $res | ForEach-Object { Write-Host "UPDATE: $($_.Title)" }
        $total += $res.Count
        Write-Host "INFO: Passe $pass - $($res.Count) mise(s) a jour posee(s)"
        $needReboot = $false
        try { $needReboot = [bool](Get-WURebootStatus -Silent) } catch { }
        if ($needReboot) {
            Write-Host "REBOOT: $total mise(s) a jour installee(s)"
            break
        }
        if ($pass -eq 3) { Write-Host "DONE: $total mise(s) a jour installee(s)" }
    }
} catch {
    Write-Host "PSWU_FAIL: $($_.Exception.Message)"
} finally {
    if ($prevPolicy -and $prevPolicy -ne 'Trusted') {
        Set-PSRepository -Name PSGallery -InstallationPolicy $prevPolicy -EA SilentlyContinue
    }
}
"""
        # Lancer un heartbeat dans un thread secondaire : indique à l'opérateur
        # que l'étape est toujours active pendant le long silence de Windows Update.
        _wupdate_stop = threading.Event()
        def _heartbeat():
            mins = 0
            while not _wupdate_stop.wait(60):
                mins += 1
                self.log(f"Windows Update en cours… ({mins} min écoulée(s))", "INFO")
        _hb = threading.Thread(target=_heartbeat, daemon=True)
        _hb.start()

        # SEC-3 : RemoteSigned — les scripts PS système (PSGallery, WUA) sont
        # signés par Microsoft et s'exécutent sans Bypass.
        code, out = run_cmd([
            "powershell", "-NoProfile", "-ExecutionPolicy", "RemoteSigned",
            "-Command", "$OutputEncoding=[System.Text.Encoding]::UTF8; " + ps_script
        ], timeout=self.WU_BUDGET_S)

        _wupdate_stop.set()

        # Budget épuisé : on n'enchaîne pas sur le repli WUA, on passe à la suite.
        # run_cmd renvoie -1 et un message « Délai dépassé » lorsqu'il tue le
        # processus au timeout.
        if code == -1 and "Délai dépassé" in (out or ""):
            self.log(
                f"Windows Update — délai de {self.WU_BUDGET_S // 60} min atteint ; "
                "les mises à jour restantes se poursuivront en arrière-plan après "
                "la remise du poste.", "WARN"
            )
            self.step(9, "done", f"Interrompu après {self.WU_BUDGET_S // 60} min")
            self.progress(10, "Étape 10/11 — BitLocker + Entra ID")
            return

        pswu_failed = False
        for line in out.splitlines():
            line = line.strip()
            if line.startswith("UPDATE:"):
                self.log(f"Mise à jour : {line[7:].strip()}", "INFO")
            elif line.startswith("INFO:"):
                self.log(line[5:].strip(), "INFO")
            elif line.startswith("REBOOT:"):
                # Le cycle s'est arrêté sur un redémarrage requis : le signaler au
                # bilan final, qui annonçait sinon « aucun redémarrage nécessaire ».
                self._reboot_pending_seen = True
                self.log(f"{line[7:].strip()} — redémarrage requis pour continuer.", "WARN")
            elif line.startswith("DONE:"):
                self.log(line[5:].strip(), "OK")
            elif line.startswith("PSWU_FAIL:"):
                msg = line[10:].strip().lower()
                pswu_failed = True
                # PSWindowsUpdate peut retourner "reboot required" dans son exception
                if any(k in msg for k in ("reboot", "restart", "redémarr", "pending")):
                    self.log(
                        "PSWindowsUpdate : redémarrage requis avant de continuer les MAJ.", "WARN"
                    )
                    self.step(9, "done", "⚠️ Redémarrage requis — MAJ au prochain boot")
                    self.progress(10, "Étape 10/11 — BitLocker + Entra ID")
                    return
                else:
                    self.log("PSWindowsUpdate indisponible — fallback WUA...", "WARN")

        if pswu_failed or code != 0:
            # Fallback : Windows Update Agent natif (COM via PowerShell)
            wua_script = r"""
$OutputEncoding = [System.Text.Encoding]::UTF8
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
try {
    $session = New-Object -ComObject Microsoft.Update.Session

    # Enregistrer Microsoft Update (Office + pilotes) et cibler ce service.
    $svcId = '7971f918-a847-4430-9279-4a52d1efe18d'
    $useMU = $false
    try {
        $sm = New-Object -ComObject Microsoft.Update.ServiceManager
        $sm.AddService2($svcId, 7, '') | Out-Null
        $useMU = $true
        Write-Host "INFO: Service Microsoft Update enregistre (Office + pilotes)"
    } catch {
        Write-Host "INFO: Microsoft Update non enregistre - $($_.Exception.Message)"
    }

    $total = 0
    for ($pass = 1; $pass -le 3; $pass++) {
        $searcher = $session.CreateUpdateSearcher()
        if ($useMU) { $searcher.ServiceID = $svcId; $searcher.ServerSelection = 3 }
        # Plus de filtre Type='Software' : il excluait TOUS les pilotes proposes
        # par Windows Update.
        $result = $searcher.Search("IsInstalled=0 and IsHidden=0")
        if ($result.Updates.Count -eq 0) {
            if ($pass -eq 1) { Write-Host "DONE: Systeme deja a jour (WUA)" }
            else { Write-Host "DONE: $total mise(s) a jour installee(s) (WUA)" }
            break
        }
        foreach ($u in $result.Updates) {
            Write-Host "UPDATE: $($u.Title)"
            # Accepter le CLUF : sans cela toute MAJ qui en exige un echoue
            # silencieusement (l'ancien code ne le faisait jamais).
            if (-not $u.EulaAccepted) { try { $u.AcceptEula() } catch { } }
        }
        $dl = $session.CreateUpdateDownloader()
        $dl.Updates = $result.Updates
        $dl.Download() | Out-Null
        $inst = $session.CreateUpdateInstaller()
        $inst.Updates = $result.Updates
        $r = $inst.Install()
        $total += $result.Updates.Count
        # OperationResultCode : 2=Succeeded 3=SucceededWithErrors 4=Failed 5=Aborted
        Write-Host "RESULT: pass=$pass code=$($r.ResultCode) reboot=$($r.RebootRequired) count=$($result.Updates.Count)"
        if ($r.ResultCode -eq 4 -or $r.ResultCode -eq 5) { break }
        if ($r.RebootRequired) { break }
        if ($pass -eq 3) { Write-Host "DONE: $total mise(s) a jour installee(s) (WUA)" }
    }
} catch {
    Write-Host "FAIL: $($_.Exception.Message)"
}
"""
            _wua_stop = threading.Event()
            def _heartbeat_wua():
                mins = 0
                while not _wua_stop.wait(60):
                    mins += 1
                    self.log(f"Windows Update (WUA) en cours… ({mins} min écoulée(s))", "INFO")
            _hb2 = threading.Thread(target=_heartbeat_wua, daemon=True)
            _hb2.start()

            # Le repli n'obtient que ce qui reste du budget de l'étape, avec un
            # plancher de 60 s pour lui laisser au moins le temps de démarrer.
            reste = max(60, int(self.WU_BUDGET_S - (time.monotonic() - wu_debut)))
            self.log(f"Repli WUA — {reste // 60} min restantes sur le budget.", "INFO")
            code2, out2 = run_cmd([
                "powershell", "-NoProfile", "-ExecutionPolicy", "RemoteSigned",
                "-Command", wua_script
            ], timeout=reste)

            _wua_stop.set()

            # OperationResultCode de l'API Windows Update. L'ancien code lisait
            # 4 comme « SucceededWithErrors / redémarrage requis » : en réalité
            # 4 = Échec et 5 = Abandonné, donc des échecs étaient journalisés en
            # simple WARN de redémarrage, et 3 passait pour un succès complet.
            WUA_RESULT = {
                0: ("WARN", "non démarré"),
                1: ("WARN", "encore en cours"),
                2: ("OK",   "réussi"),
                3: ("WARN", "réussi avec erreurs"),
                4: ("FAIL", "échec"),
                5: ("FAIL", "abandonné"),
            }
            for line in out2.splitlines():
                line = line.strip()
                if line.startswith("UPDATE:"):
                    self.log(f"Mise à jour : {line[7:].strip()}", "INFO")
                elif line.startswith("INFO:"):
                    self.log(line[5:].strip(), "INFO")
                elif line.startswith("RESULT:"):
                    m = re.search(r"pass=(\d+)\s+code=(\d+)\s+reboot=(\w+)\s+count=(\d+)", line)
                    if m:
                        p, rc, rb, cnt = (int(m.group(1)), int(m.group(2)),
                                          m.group(3).lower() == "true", int(m.group(4)))
                        lvl, label = WUA_RESULT.get(rc, ("WARN", f"code {rc}"))
                        self.log(
                            f"Passe {p} — {cnt} mise(s) à jour : {label}.", lvl
                        )
                        if lvl != "OK":
                            self.log(
                                "Vérifier l'historique dans Paramètres > Windows Update.",
                                "WARN"
                            )
                        if rb:
                            self._reboot_pending_seen = True
                            self.log("Windows Update : redémarrage requis.", "WARN")
                    else:
                        self.log(line, "INFO")
                elif line.startswith("DONE:"):
                    self.log(line[5:].strip(), "OK")
                elif line.startswith("FAIL:"):
                    msg = line[5:].strip().lower()
                    if any(k in msg for k in ("reboot", "restart", "pending")):
                        self.log("WUA : redémarrage requis avant de continuer les MAJ.", "WARN")
                        self.step(9, "done", "⚠️ Redémarrage requis — MAJ au prochain boot")
                        self.progress(10, "Étape 10/11 — BitLocker + Entra ID")
                        return
                    self.log(f"Windows Update WUA : {line[5:].strip()}", "FAIL")
                    self.log("Lancez Windows Update manuellement : Paramètres > Windows Update", "WARN")

        self.step(9, "done", "Windows Update terminé")
        self.progress(10, "Étape 10/11 — BitLocker + Entra ID")

    # ─────────────────────────────────────────────────────────────────────────
    # ÉTAPE 10 — BitLocker + sauvegarde de la clé dans Entra ID
    # ─────────────────────────────────────────────────────────────────────────

    PS_BITLOCKER_ENTRA = r"""
$OutputEncoding = [System.Text.Encoding]::UTF8
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$ErrorActionPreference = 'Stop'
try {
    # 1) Vérifier la jonction Entra ID (natif ou hybride)
    $ds = (dsregcmd /status) | Out-String
    if ($ds -notmatch 'AzureAdJoined\s*:\s*YES') {
        Write-Host 'FAIL: Appareil non joint a Entra ID - sauvegarde impossible'
        exit 1
    }

    # 2) Vérifier le TPM
    $tpm = Get-Tpm
    if (-not $tpm.TpmPresent -or -not $tpm.TpmReady) {
        Write-Host 'FAIL: TPM absent ou non initialise'
        exit 1
    }

    # 3) Activer BitLocker sur C: si nécessaire (TPM, XTS-AES 256, espace utilisé)
    $vol = Get-BitLockerVolume -MountPoint 'C:'
    if ($vol.VolumeStatus -eq 'FullyDecrypted') {
        Enable-BitLocker -MountPoint 'C:' -EncryptionMethod XtsAes256 `
            -UsedSpaceOnly -TpmProtector -SkipHardwareTest | Out-Null
        Write-Host 'INFO: BitLocker active (chiffrement en cours en arriere-plan)'
    } else {
        Write-Host "INFO: BitLocker deja actif (statut: $($vol.VolumeStatus))"
    }

    # 4) Garantir un protecteur RecoveryPassword (le TPM seul ne se sauvegarde pas)
    $vol = Get-BitLockerVolume -MountPoint 'C:'
    $rp  = $vol.KeyProtector | Where-Object { $_.KeyProtectorType -eq 'RecoveryPassword' }
    if (-not $rp) {
        Add-BitLockerKeyProtector -MountPoint 'C:' -RecoveryPasswordProtector | Out-Null
        $rp = (Get-BitLockerVolume -MountPoint 'C:').KeyProtector |
              Where-Object { $_.KeyProtectorType -eq 'RecoveryPassword' }
        Write-Host 'INFO: Protecteur de recuperation cree'
    }

    # 5) Sauvegarder chaque protecteur RecoveryPassword dans Entra ID
    foreach ($p in $rp) {
        BackupToAAD-BitLockerKeyProtector -MountPoint 'C:' -KeyProtectorId $p.KeyProtectorId
        Write-Host "OK: Cle $($p.KeyProtectorId) envoyee vers Entra ID"
    }

    # 6) Confirmation via le journal d'événements (event 845 = backup réussi)
    # On attend 10s — sur réseau lent ou Entra ID congestionné, l'event
    # peut prendre plusieurs secondes à être écrit après la cmdlet.
    Start-Sleep -Seconds 10
    $evt = Get-WinEvent -FilterHashtable @{
        LogName = 'Microsoft-Windows-BitLocker/BitLocker Management'; Id = 845
    } -MaxEvents 1 -ErrorAction SilentlyContinue
    if ($evt -and $evt.TimeCreated -gt (Get-Date).AddMinutes(-10)) {
        Write-Host "DONE: Sauvegarde confirmee dans Entra ID (event 845 a $($evt.TimeCreated.ToString('HH:mm:ss')))"
        Write-Host "INFO: Pour verifier → Portail Entra ID > Devices > $env:COMPUTERNAME > BitLocker keys"
    } else {
        Write-Host 'WARN: Event 845 non trouve - la cle a peut-etre ete envoyee mais non confirmee'
        Write-Host "INFO: Verifiez dans → Portail Entra ID > Devices > $env:COMPUTERNAME > BitLocker keys"
    }
} catch {
    Write-Host "FAIL: $($_.Exception.Message)"
    exit 1
}
"""

    def step10_bitlocker(self):
        self.step(10, "active", "BitLocker + Entra ID...")
        self.log("BITLOCKER — SAUVEGARDE CLÉ ENTRA ID", "SECTION")
        # NOTE sécurité : le mot de passe de récupération n'est JAMAIS loggé,
        # seulement le KeyProtectorId (le log atterrit sur le bureau).

        # SEC-3 : RemoteSigned — les cmdlets BitLocker sont signées par Microsoft.
        code, out = run_cmd([
            "powershell", "-NoProfile", "-ExecutionPolicy", "RemoteSigned",
            "-Command", self.PS_BITLOCKER_ENTRA
        ])

        had_fail = False
        had_done = False
        for line in out.splitlines():
            line = line.strip()
            if line.startswith("OK:"):
                self.log(line[3:].strip(), "OK")
            elif line.startswith("INFO:"):
                self.log(line[5:].strip(), "INFO")
            elif line.startswith("WARN:"):
                self.log(line[5:].strip(), "WARN")
            elif line.startswith("DONE:"):
                self.log(line[5:].strip(), "OK")
                had_done = True
            elif line.startswith("FAIL:"):
                self.log(line[5:].strip(), "FAIL")
                had_fail = True

        # On se fie au contenu parsé plutôt qu'au code de sortie PS :
        # le script PS peut retourner 0 même en cas d'erreur partielle.
        if had_fail or (not had_done and code != 0):
            self.step(10, "fail", "Échec — voir le log")
        else:
            self.step(10, "done", "Clé sauvegardée dans Entra ID")
        self.progress(11, "✅ Installation terminée !")

    # ─────────────────────────────────────────────────────────────────────────
    # SAUVEGARDE DU LOG
    # ─────────────────────────────────────────────────────────────────────────

    # ─────────────────────────────────────────────────────────────────────────
    # INVENTAIRE MATÉRIEL
    # ─────────────────────────────────────────────────────────────────────────

    # Script CIM unique : un seul processus PowerShell pour tout collecter.
    # Chaque valeur est émise sous la forme « INV|clé|valeur » — parsing par
    # sentinelle, insensible à tout bruit résiduel dans la sortie (leçon tirée
    # du bug de détection NVIDIA). Chaque bloc a son propre try/catch : une
    # requête qui échoue n'empêche jamais les autres de remonter.
    INVENTORY_PS = r"""
function Emit($k, $v) {
    if ($null -ne $v -and "$v".Trim() -ne '') {
        Write-Output ("INV|" + $k + "|" + ("$v" -replace '[\r\n]+', ' ').Trim())
    }
}

# Choisit le numéro de série disque le plus exploitable parmi plusieurs sources.
# Selon le pilote NVMe, Windows expose soit le numéro imprimé sur l'étiquette
# (ex. 2343X801559), soit l'EUI-64 du contrôleur (ex. 0025_38CC_51B0_1788), qui
# n'est PAS le numéro de série et ne sert à rien pour l'inventaire ou le SAV.
# On écarte donc les valeurs de forme EUI et on garde le premier vrai numéro.
function Get-CleanSerial($candidates) {
    foreach ($c in $candidates) {
        if ($null -eq $c) { continue }
        $s = "$c".Trim().TrimEnd('.')
        # AdapterSerialNumber arrive rembourré et suffixé : « S7G8NF1X923400      _0001 ».
        $s = ($s -replace '\s+_\d+$', '') -replace '\s+', ''
        if ($s -eq '') { continue }
        # EUI-64 : 4 groupes de 4 chiffres hexa (avec ou sans séparateur)
        if ($s -match '^[0-9A-Fa-f]{4}([ _-]?[0-9A-Fa-f]{4}){3}$') { continue }
        return $s
    }
    # Aucune source « propre » : renvoyer la première valeur non vide plutôt que rien.
    foreach ($c in $candidates) {
        if ($null -ne $c -and "$c".Trim() -ne '') { return "$c".Trim().TrimEnd('.') }
    }
    return $null
}

# ── Identité machine ──────────────────────────────────────────────────────
try {
    $cs   = Get-CimInstance Win32_ComputerSystem        -ErrorAction SilentlyContinue
    $bios = Get-CimInstance Win32_BIOS                  -ErrorAction SilentlyContinue
    $csp  = Get-CimInstance Win32_ComputerSystemProduct -ErrorAction SilentlyContinue

    Emit 'Fabricant' $cs.Manufacturer
    Emit 'Modele'    $cs.Model
    # Sur Lenovo, Model contient le code machine (ex. 21F6CTO1WW) et le nom
    # commercial (ex. ThinkPad P14s Gen 4) est dans ComputerSystemProduct.Version.
    if ($csp.Version -and $csp.Version -ne $cs.Model -and
        $csp.Version -notmatch '^(None|System Version|Default string)$') {
        Emit 'ModeleCommercial' $csp.Version
    }
    Emit 'NumeroSerie' $bios.SerialNumber
    Emit 'BIOS' $bios.SMBIOSBIOSVersion
    if ($bios.ReleaseDate) { Emit 'BIOSDate' ($bios.ReleaseDate.ToString('yyyy-MM-dd')) }
} catch {}

# ── Processeur ────────────────────────────────────────────────────────────
try {
    $cpu = Get-CimInstance Win32_Processor -ErrorAction SilentlyContinue |
           Select-Object -First 1
    Emit 'CPU' $cpu.Name
    Emit 'CPUCoeurs' ("$($cpu.NumberOfCores) coeurs / $($cpu.NumberOfLogicalProcessors) threads")
} catch {}

# ── Mémoire ───────────────────────────────────────────────────────────────
try {
    $ram = @(Get-CimInstance Win32_PhysicalMemory -ErrorAction SilentlyContinue)
    if ($ram.Count -gt 0) {
        $totalGB = [math]::Round((($ram | Measure-Object Capacity -Sum).Sum) / 1GB, 0)
        $slots = (Get-CimInstance Win32_PhysicalMemoryArray -ErrorAction SilentlyContinue |
                  Select-Object -First 1).MemoryDevices
        if ($slots) { Emit 'RAMTotal' "$totalGB Go ($($ram.Count) barrette(s) sur $slots emplacement(s))" }
        else        { Emit 'RAMTotal' "$totalGB Go ($($ram.Count) barrette(s))" }
        $i = 0
        foreach ($m in $ram) {
            $i++
            $cap = [math]::Round($m.Capacity / 1GB, 0)
            $spd = if ($m.Speed) { " @ $($m.Speed) MHz" } else { "" }
            $pn  = if ($m.PartNumber) { " — $($m.PartNumber.Trim())" } else { "" }
            Emit "RAM$i" ("$cap Go$spd$pn")
        }
    }
} catch {}

# ── Disques ───────────────────────────────────────────────────────────────
try {
    $pd = @(Get-CimInstance -Namespace root\Microsoft\Windows\Storage `
                            -ClassName MSFT_PhysicalDisk -ErrorAction SilentlyContinue)
    # Sources complémentaires pour le numéro de série (cf. Get-CleanSerial) :
    # Win32_DiskDrive et MSFT_Disk exposent souvent le numéro de l'étiquette
    # là où MSFT_PhysicalDisk ne renvoie que l'EUI-64 du contrôleur NVMe.
    $w32  = @(Get-CimInstance Win32_DiskDrive -ErrorAction SilentlyContinue)
    $mdsk = @(Get-CimInstance -Namespace root\Microsoft\Windows\Storage `
                              -ClassName MSFT_Disk -ErrorAction SilentlyContinue)
    if ($pd.Count -gt 0) {
        $i = 0
        foreach ($d in $pd) {
            $i++
            $type = switch ($d.MediaType) { 3 {'HDD'} 4 {'SSD'} 5 {'SCM'} default {''} }
            $bus  = switch ($d.BusType)   { 17 {'NVMe'} 11 {'SATA'} 7 {'USB'} default {''} }
            $sz   = [math]::Round($d.Size / 1GB, 0)
            Emit "Disque$i" (("$($d.FriendlyName) — $sz Go $type $bus") -replace '\s+', ' ')
            # Corréler les trois classes sur le même disque physique :
            # MSFT_PhysicalDisk.DeviceId == Win32_DiskDrive.Index == MSFT_Disk.Number
            $num = $null
            if ($d.DeviceId -match '^\d+$') { $num = [int]$d.DeviceId }
            $sw = $null; $sm = $null
            if ($null -ne $num) {
                $sw = ($w32  | Where-Object { $_.Index  -eq $num } | Select-Object -First 1).SerialNumber
                $sm = ($mdsk | Where-Object { $_.Number -eq $num } | Select-Object -First 1).SerialNumber
            }
            # FruId et AdapterSerialNumber EN PREMIER : sur NVMe, ce sont les
            # seules propriétés qui portent le numéro imprimé sur l'étiquette.
            # SerialNumber / UniqueId des trois classes renvoient tous l'EUI-64
            # du contrôleur (vérifié : Windows le préfixe lui-même « eui. »).
            $serial = Get-CleanSerial @($d.FruId, $d.AdapterSerialNumber,
                                        $sw, $sm, $d.SerialNumber)
            if ($serial) { Emit "DisqueSerie$i" $serial }
            if ($d.FirmwareVersion) { Emit "DisqueFirmware$i" ($d.FirmwareVersion.Trim()) }
        }
    } else {
        # Repli si l'espace de noms Storage est indisponible.
        $i = 0
        foreach ($d in $w32) {
            $i++
            $sz = [math]::Round($d.Size / 1GB, 0)
            Emit "Disque$i" "$($d.Model) — $sz Go"
            $serial = Get-CleanSerial @($d.SerialNumber)
            if ($serial) { Emit "DisqueSerie$i" $serial }
        }
    }
    $c = Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='C:'" -ErrorAction SilentlyContinue
    if ($c) {
        Emit 'VolumeC' ("$([math]::Round($c.Size/1GB,0)) Go total / $([math]::Round($c.FreeSpace/1GB,0)) Go libres")
    }
} catch {}

# ── Cartes réseau (physiques uniquement) ──────────────────────────────────
try {
    # PhysicalAdapter + PNPDeviceID PCI/USB : exclut les adaptateurs virtuels
    # (VPN, Hyper-V, loopback) qui sont en ROOT\* et pollueraient l'inventaire.
    $nics = @(Get-CimInstance Win32_NetworkAdapter -ErrorAction SilentlyContinue |
              Where-Object {
                  $_.PhysicalAdapter -eq $true -and $_.MACAddress -and
                  ($_.PNPDeviceID -like 'PCI\*' -or $_.PNPDeviceID -like 'USB\*')
              })
    $i = 0
    foreach ($n in $nics) {
        $i++
        Emit "MAC$i" "$($n.MACAddress) — $($n.Name)"
    }
} catch {}
"""

    # Ordre d'affichage ; les familles dynamiques (RAM/Disque/MAC) sont ajoutées
    # ensuite par préfixe, triées naturellement.
    INVENTORY_LABELS = [
        ("Fabricant",       "Fabricant"),
        ("ModeleCommercial", "Modèle"),
        ("Modele",          "Code machine"),
        ("NumeroSerie",     "N° de série"),
        ("BIOS",            "BIOS"),
        ("BIOSDate",        "Date BIOS"),
        ("CPU",             "Processeur"),
        ("CPUCoeurs",       "Cœurs"),
        ("RAMTotal",        "Mémoire"),
        ("VolumeC",         "Volume C:"),
    ]

    def collect_inventory(self) -> dict:
        """Collecte l'inventaire matériel via CIM. Retourne un dict clé → valeur.

        Ne lève jamais et ne bloque jamais l'installation : en cas d'échec, on
        retourne ce qui a pu être lu (éventuellement un dict vide).
        """
        try:
            code, out = run_cmd(self._ps_encoded(self.INVENTORY_PS), timeout=90)
        except Exception as exc:
            self.log(f"Inventaire — collecte impossible : {exc}", "WARN")
            return {}
        inv = {}
        for line in (out or "").splitlines():
            line = line.strip()
            if not line.startswith("INV|"):
                continue
            parts = line.split("|", 2)
            if len(parts) == 3 and parts[1].strip() and parts[2].strip():
                inv.setdefault(parts[1].strip(), parts[2].strip())
        return inv

    def log_inventory(self):
        """Journalise l'inventaire matériel et le mémorise dans self.inventory.

        Purement informatif : aucune décision d'installation n'en dépend, donc
        un échec ici n'a aucun impact sur la suite du provisioning.
        """
        self.log("INVENTAIRE MATÉRIEL", "SECTION")
        inv = self.collect_inventory()
        self.inventory = inv

        if not inv:
            self.log("Inventaire indisponible — requêtes CIM sans réponse.", "WARN")
            return

        shown = set()
        for key, label in self.INVENTORY_LABELS:
            if key in inv:
                self.log(f"{label:<14}: {inv[key]}", "INFO")
                shown.add(key)

        # Familles dynamiques : RAM1..n, Disque1..n, MAC1..n
        for prefix, label in (("RAM", "Barrette"), ("Disque", "Disque"), ("MAC", "MAC")):
            keys = sorted(
                (k for k in inv if k not in shown and re.fullmatch(prefix + r"\d+", k)),
                key=lambda k: int(re.sub(r"\D", "", k))
            )
            for k in keys:
                idx = re.sub(r"\D", "", k)
                self.log(f"{label + ' ' + idx:<14}: {inv[k]}", "INFO")
                shown.add(k)
                # Détails rattachés au disque courant (n° de série, firmware).
                if prefix == "Disque":
                    for sub_key, sub_label in (("DisqueSerie", "N° série"),
                                               ("DisqueFirmware", "Firmware")):
                        val = inv.get(f"{sub_key}{idx}")
                        if val:
                            self.log(f"{'  ↳ ' + sub_label:<14}: {val}", "INFO")
                            shown.add(f"{sub_key}{idx}")

    def save_log(self):
        """Ajoute le pied de page (fin/durée) au log écrit au fil de l'eau.

        Le log étant écrit directement sur le bureau, aucun raccourci n'est créé :
        le fichier est déjà à l'endroit où le technicien le cherche.
        """
        duration = round((datetime.now() - self.start_time).total_seconds() / 60, 1)
        footer = (
            "\n══════════════════════════════════════════════════════════════════\n"
            f"Date/Heure fin   : {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n"
            f"Durée totale     : {duration} minutes\n"
        )
        try:
            if self._log_fh is not None:
                self._log_fh.write(footer)
                self._log_fh.flush()
                self.log(f"Log sauvegardé : {self.log_path}", "OK")
            else:
                self.log("Log fichier indisponible (bureau inaccessible).", "WARN")
        except Exception as exc:
            self.log(f"Impossible de finaliser le log : {exc}", "WARN")
        finally:
            self._close_log_file()

    # ─────────────────────────────────────────────────────────────────────────
    # POINT D'ENTRÉE DU THREAD
    # ─────────────────────────────────────────────────────────────────────────

    def run(self):
        # Protection anti-veille : désactivée dès le début, restaurée dans step8.
        self._save_and_disable_sleep()

        # ── Inventaire matériel ───────────────────────────────────────────────
        # Collecté avant toute installation : l'état matériel est ainsi consigné
        # tel qu'à la réception du poste. Purement informatif — n'influence
        # aucune étape et ne peut pas interrompre le provisioning.
        self.log_inventory()

        # ── Test de disponibilité de winget ───────────────────────────────────
        self.log("TEST WINGET", "SECTION")
        code_w, out_w = run_cmd(["winget", "--version"], timeout=15)
        if code_w == 0:
            ver_w = out_w.strip().splitlines()[0] if out_w.strip() else "inconnu"
            self.log(f"Winget disponible : {ver_w}", "OK")
            self._winget_ok = True
            # Mettre à jour UNIQUEMENT la source « winget » (--name winget).
            # On évite « winget source update » global qui interroge aussi
            # msstore et échoue avec 0x8A15005E (certificate pinning) derrière
            # un proxy à inspection SSL, polluant tout le reste.
            self.log("Mise à jour de la source winget...", "CMD")
            # NOTE : pas de --accept-source-agreements ici. `winget source update`
            # ne l'accepte pas et retourne 0x8A150002 (INVALID_CL_ARGUMENTS) en
            # n'affichant que sa bannière — c'était l'échec observé en production.
            code_su, out_su = run_cmd([
                "winget", "source", "update", "--name", "winget"
            ], timeout=60)
            if code_su == 0:
                self.log("Source winget mise à jour.", "OK")
            else:
                self.log(
                    f"Échec mise à jour de la source winget (code {code_su}). "
                    "Les installs sont tentées quand même via --source winget.",
                    "WARN"
                )
                for line in (out_su or "").strip().splitlines()[:3]:
                    if line.strip():
                        self.log(f"  winget: {line.strip()}", "CMD")
        else:
            self.log(
                "Winget indisponible ou non initialisé — "
                "les installations passeront par téléchargement direct.", "WARN"
            )
            self._winget_ok = False

        # ── Boucle d'étapes ───────────────────────────────────────────────────
        # _check_stop() est appelé avant chaque étape : si la fenêtre a été
        # fermée, InterruptedError est levée et capturée dans le finally.
        etapes = [
            (1,    self.step1_folders),
            (2,    self.step2_docs),
            (3,    self.step3_shortcuts),
            (4,    self.step4_computer_name),
            (None, self.step4b_nouvelle_embauche),
            (5,    self.step5_office),
            (6,    self.step6_software),
            (7,    self.step7_edge_bookmarks),
            (8,    self.step8_windows_config),
            (9,    self.step9_windows_update),
            (10,   self.step10_bitlocker),
        ]
        try:
            for idx, fn in etapes:
                self._check_stop()
                try:
                    fn()
                except InterruptedError:
                    raise  # propager vers le finally
                except Exception as exc:
                    if idx is not None:
                        self.log(f"Étape {idx} — erreur inattendue : {exc}", "FAIL")
                        self.step(idx, "fail", "Erreur — voir le log")
                    else:
                        self.log(f"Étape 4b — erreur inattendue : {exc}", "WARN")

            # Vérification finale + fiche de remise, AVANT le nettoyage : la
            # fiche doit refléter l'état du poste tel qu'il est livré.
            try:
                checks = self._final_verification()
                self._write_handover_sheet(checks)
            except Exception as exc:
                self.log(f"Vérification finale — erreur : {exc}", "WARN")

            # Toutes les étapes terminées : nettoyage du dossier de déploiement.
            self._cleanup_deploy_folder()
        except InterruptedError as exc:
            self.log(str(exc), "WARN")
        finally:
            self.log("FIN DU SCRIPT", "SECTION")
            self._log_summary()
            self._check_reboot_required()
            self.log("Script terminé normalement.", "OK")
            self.save_log()
            self.sig_done.emit()

    def _cleanup_deploy_folder(self):
        """Supprime le dossier de déploiement compagnon (C:\\LGS_Deploy) en fin de
        script. Best-effort : les fichiers encore verrouillés sont ignorés, et une
        erreur ici n'interrompt jamais le script."""
        try:
            if not LGS_DEPLOY_DIR.exists():
                return
            self.log(f"Nettoyage : suppression de {LGS_DEPLOY_DIR}...", "CMD")

            def _onerror(func, path, _exc):
                # Retirer un éventuel attribut lecture seule puis réessayer.
                try:
                    os.chmod(path, 0o777)
                    func(path)
                except Exception:
                    pass

            shutil.rmtree(LGS_DEPLOY_DIR, onerror=_onerror)
            if LGS_DEPLOY_DIR.exists():
                self.log(
                    "Dossier de déploiement partiellement supprimé "
                    "(fichiers en cours d'utilisation ignorés).", "WARN"
                )
            else:
                self.log("Dossier de déploiement supprimé.", "OK")
        except Exception as exc:
            self.log(f"Nettoyage LGS_Deploy — erreur : {exc}", "WARN")

    # ─────────────────────────────────────────────────────────────────────────
    # VÉRIFICATION FINALE (self-test) + FICHE DE REMISE
    # ─────────────────────────────────────────────────────────────────────────

    def _final_verification(self) -> list:
        """Contrôle l'état réel du poste en fin de provisionnement.

        Ne modifie rien : chaque point est re-mesuré sur la machine plutôt que
        déduit du déroulé du script — une étape peut « s'être bien passée » sans
        que le résultat soit là (cas constaté avec winget qui retourne 0).

        Retourne une liste de dicts {label, statut, detail} ; statut ∈
        OK / FAIL / WARN / SKIP.
        """
        self.log("VÉRIFICATION FINALE", "SECTION")
        checks = []

        def add(label, statut, detail=""):
            checks.append({"label": label, "statut": statut, "detail": detail})
            niveau = {"OK": "OK", "FAIL": "FAIL", "WARN": "WARN", "SKIP": "SKIP"}[statut]
            self.log(f"{label} — {detail or statut}", niveau)

        # 1. Nom d'ordinateur
        voulu = (self.machine_info.get("computer_name") or "").strip()
        actuel = platform.node()
        if not voulu:
            add("Nom d'ordinateur", "SKIP", "aucun nom demandé")
        elif voulu.upper() == actuel.upper():
            add("Nom d'ordinateur", "OK", actuel)
        else:
            add("Nom d'ordinateur", "WARN",
                f"« {actuel} » — « {voulu} » effectif après redémarrage")

        # 2. Dossier et raccourci CAT
        desktop = get_desktop()
        add("Dossier CAT", "OK" if (desktop / "CAT").is_dir() else "FAIL",
            str(desktop / "CAT"))
        add("Raccourci CAT.lnk", "OK" if (desktop / "CAT.lnk").exists() else "FAIL", "")

        # 3. Logiciels du catalogue
        for cle, nom in (("office", "Microsoft 365 Apps"), ("firefox", "Firefox"),
                         ("chrome", "Google Chrome"), ("slack", "Slack"),
                         ("box_for_office", "Box for Office"), ("box_tools", "Box Tools"),
                         ("adobe", "Adobe Acrobat Reader"), ("intel_dsa", "Intel DSA")):
            entry = LOGICIELS[cle]
            present = self._soft_present(entry)
            if cle == "intel_dsa" and not present:
                present = is_service_installed(entry.get("service_name", ""))
            add(nom, "OK" if present else "FAIL", "installé" if present else "ABSENT")

        # 4. Lenovo Commercial Vantage (uniquement sur matériel Lenovo)
        _, fab = run_cmd(self._ps_encoded(
            "Write-Output ('MFG=' + (Get-CimInstance Win32_ComputerSystem"
            " -ErrorAction SilentlyContinue).Manufacturer)"), timeout=30)
        est_lenovo = "lenovo" in (fab or "").lower()
        if est_lenovo:
            _, out_v = run_cmd(self._ps_encoded(
                "if (Get-AppxPackage -Name '*Vantage*') { Write-Output 'YES' }"), timeout=45)
            ok_v = "YES" in (out_v or "")
            add("Lenovo Commercial Vantage", "OK" if ok_v else "FAIL",
                "installé" if ok_v else "ABSENT — déposer le paquet de déploiement")
        else:
            add("Lenovo Commercial Vantage", "SKIP", "poste non-Lenovo")

        # 5. BitLocker : chiffrement ET sauvegarde de la clé
        _, out_bl = run_cmd(self._ps_encoded(
            "$v = Get-BitLockerVolume -MountPoint 'C:' -ErrorAction SilentlyContinue\n"
            "if ($v) { Write-Output ('BL=' + $v.ProtectionStatus + '|' + $v.EncryptionPercentage) }"
        ), timeout=60)
        m_bl = re.search(r"BL=(\w+)\|(\d+)", out_bl or "")
        if m_bl:
            protege = m_bl.group(1).lower() in ("on", "1")
            add("BitLocker (C:)", "OK" if protege else "FAIL",
                f"protection {m_bl.group(1)}, chiffré à {m_bl.group(2)} %")
        else:
            add("BitLocker (C:)", "FAIL", "état illisible")

        # 6. Jonction Entra ID
        _, out_dsr = run_cmd(["dsregcmd", "/status"], timeout=60)
        joint = re.search(r"AzureAdJoined\s*:\s*YES", out_dsr or "", re.I)
        add("Jonction Entra ID", "OK" if joint else "WARN",
            "AzureAdJoined : YES" if joint else "non joint ou état illisible")

        # 7. Écran de veille (ruche d'un utilisateur réel, pas celle de l'admin)
        sids = self._loaded_user_sids()
        ss_ok = False
        for sid in sids:
            try:
                with winreg.OpenKey(winreg.HKEY_USERS,
                                    sid + r"\Control Panel\Desktop") as k:
                    if (winreg.QueryValueEx(k, "ScreenSaveTimeOut")[0] == "600"
                            and winreg.QueryValueEx(k, "ScreenSaverIsSecure")[0] == "1"):
                        ss_ok = True
            except OSError:
                continue
        add("Écran de veille", "OK" if ss_ok else "WARN",
            "10 min + verrouillage" if ss_ok else "non confirmé sur une ruche utilisateur")

        # 8. Configuration régionale
        reg_ok = False
        for sid in sids:
            try:
                with winreg.OpenKey(winreg.HKEY_USERS,
                                    sid + r"\Control Panel\International") as k:
                    if winreg.QueryValueEx(k, "sShortDate")[0] == "yyyy-MM-dd":
                        reg_ok = True
            except OSError:
                continue
        add("Configuration régionale", "OK" if reg_ok else "WARN",
            "fr-CA, date ISO, 24 h" if reg_ok else "non confirmée")

        nb_fail = sum(1 for c in checks if c["statut"] == "FAIL")
        nb_warn = sum(1 for c in checks if c["statut"] == "WARN")
        if nb_fail:
            self.log(f"Vérification : {nb_fail} point(s) en échec, "
                     f"{nb_warn} avertissement(s).", "FAIL")
        elif nb_warn:
            self.log(f"Vérification : aucun échec, {nb_warn} avertissement(s).", "WARN")
        else:
            self.log("Vérification : tous les points sont conformes.", "OK")
        return checks

    HANDOVER_CSS = """
body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:24px;background:#f4f6f8;color:#1b1f23}
.wrap{max-width:900px;margin:0 auto;background:#fff;border-radius:8px;
      box-shadow:0 1px 4px rgba(0,0,0,.12);overflow:hidden}
header{background:#0f1a2b;color:#fff;padding:20px 28px}
header h1{margin:0;font-size:20px;letter-spacing:.5px}
header p{margin:4px 0 0;font-size:13px;opacity:.75}
section{padding:20px 28px;border-top:1px solid #e6e9ed}
h2{font-size:14px;text-transform:uppercase;letter-spacing:.8px;color:#5a6472;margin:0 0 12px}
table{width:100%;border-collapse:collapse;font-size:13px}
td,th{padding:7px 10px;text-align:left;border-bottom:1px solid #eef1f4;vertical-align:top}
th{width:34%;color:#5a6472;font-weight:600}
.badge{display:inline-block;padding:2px 9px;border-radius:11px;font-size:11px;font-weight:700}
.OK{background:#e3f6e8;color:#136b2e}.FAIL{background:#fde8e8;color:#9b1c1c}
.WARN{background:#fdf3e0;color:#8a5a00}.SKIP{background:#eceff2;color:#5a6472}
.sum{font-size:13px;margin:0 0 14px;padding:10px 14px;border-radius:6px}
.sum.ok{background:#e3f6e8;color:#136b2e}.sum.ko{background:#fde8e8;color:#9b1c1c}
.sum.wa{background:#fdf3e0;color:#8a5a00}
footer{padding:14px 28px;font-size:11px;color:#8a94a0;background:#fafbfc}
@media print{body{background:#fff;padding:0}.wrap{box-shadow:none}}
"""

    def _write_handover_sheet(self, checks: list) -> Path | None:
        """Génère la fiche de remise HTML (inventaire + vérification finale).

        Déposée sur le bureau à côté du journal. Sert de preuve de conformité
        pour le technicien et d'enregistrement d'actif pour l'organisation.
        Purement documentaire : un échec ici n'a aucun impact sur le poste.
        """
        try:
            from html import escape

            inv = self.inventory or {}
            cn = self.machine_info.get("computer_name") or platform.node()
            ts = datetime.now()

            nb_fail = sum(1 for c in checks if c["statut"] == "FAIL")
            nb_warn = sum(1 for c in checks if c["statut"] == "WARN")
            if nb_fail:
                cls, msg = "ko", f"{nb_fail} point(s) en échec, {nb_warn} avertissement(s) — à traiter avant remise."
            elif nb_warn:
                cls, msg = "wa", f"Aucun échec, {nb_warn} avertissement(s) à vérifier."
            else:
                cls, msg = "ok", "Tous les points de contrôle sont conformes."

            def lignes(d):
                return "".join(
                    f"<tr><th>{escape(str(k))}</th><td>{escape(str(v))}</td></tr>"
                    for k, v in d.items()
                )

            ident = {
                "Nom du poste": cn,
                "Provisionné le": ts.strftime("%Y-%m-%d %H:%M"),
                "Technicien": os.environ.get("USERNAME", "inconnu"),
                "Durée": f"{round((ts - self.start_time).total_seconds()/60, 1)} minutes",
                "LGS InstalleX": f"v{INSTALLEX_VERSION}",
            }

            ctrl = "".join(
                f'<tr><th>{escape(c["label"])}</th><td>'
                f'<span class="badge {c["statut"]}">{c["statut"]}</span> '
                f'{escape(c["detail"])}</td></tr>'
                for c in checks
            )

            html = (
                "<!DOCTYPE html><html lang=\"fr\"><head><meta charset=\"utf-8\">"
                f"<title>Fiche de remise — {escape(cn)}</title>"
                f"<style>{self.HANDOVER_CSS}</style></head><body><div class=\"wrap\">"
                "<header><h1>Fiche de remise — poste de travail</h1>"
                "<p>Groupe LGS, une société IBM — document généré automatiquement</p></header>"
                f"<section><h2>Identification</h2><table>{lignes(ident)}</table></section>"
                f"<section><h2>Vérification finale</h2>"
                f"<p class=\"sum {cls}\">{escape(msg)}</p>"
                f"<table>{ctrl}</table></section>"
                + (f"<section><h2>Inventaire matériel</h2><table>{lignes(inv)}</table></section>"
                   if inv else
                   "<section><h2>Inventaire matériel</h2><p style=\"font-size:13px;color:#8a94a0\">"
                   "Inventaire indisponible.</p></section>")
                + f"<footer>LGS InstalleX v{INSTALLEX_VERSION} — "
                  f"{ts.strftime('%Y-%m-%d %H:%M:%S')}</footer>"
                "</div></body></html>"
            )

            dest = get_desktop() / f"Fiche_Remise_{cn}_{ts.strftime('%Y-%m-%d_%H-%M-%S')}.html"
            dest.write_text(html, encoding="utf-8")
            self.log(f"Fiche de remise créée : {dest.name}", "OK")
            return dest
        except Exception as exc:
            self.log(f"Fiche de remise — non générée : {exc}", "WARN")
            return None

    def _log_summary(self):
        """Affiche un récapitulatif des actions effectuées en fin d'installation."""
        self.log("RÉCAPITULATIF DES ACTIONS", "SECTION")
        actions = [
            "Création du dossier CAT sur le bureau",
            "Extraction des fichiers de documentation",
            "Nom d'ordinateur configuré",
            "Microsoft Office — installation tentée",
            "Logiciels : Firefox, Chrome, Slack, Box for Office, Box Tools, Adobe, Intel DSA",
            "Favoris Microsoft Edge configurés",
            "Configuration Windows (écran de veille, démarrage rapide, veille)",
            "Windows Update — recherche et installation",
            "BitLocker — sauvegarde clé dans Entra ID",
        ]
        for action in actions:
            self.log(f"  • {action}", "INFO")
        self.log("Actions manuelles recommandées :", "INFO")
        self.log("  • Vérifier le changement de nom d'ordinateur", "INFO")
        self.log("  • Importation des favoris Firefox / Chrome si nécessaire", "INFO")
        self.log("  • Transfert de données si c'est un refresh", "INFO")
        self.log("  • Vérification complète de la checklist LGS", "INFO")

    def _check_reboot_required(self):
        """Vérifie si un redémarrage est requis.

        Trois sources, et non plus seulement le registre : le renommage du poste
        et un redémarrage déjà en attente étaient ignorés, d'où le message
        contradictoire « Aucun redémarrage nécessaire » alors que la machine
        venait d'être renommée et qu'un reboot était signalé plus haut.
        """
        reasons = []

        # 1. Renommage effectué durant cette exécution → reboot obligatoire.
        if getattr(self, "_renamed", False):
            reasons.append("changement de nom d'ordinateur")

        # 2. Redémarrage déjà signalé en attente durant l'exécution.
        if getattr(self, "_reboot_pending_seen", False):
            reasons.append("mises à jour Windows en attente")

        # 3. Clés de registre Windows Update / CBS.
        reboot_keys = [
            (winreg.HKEY_LOCAL_MACHINE,
             r"SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired"),
            (winreg.HKEY_LOCAL_MACHINE,
             r"SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending"),
        ]
        for hive, path in reboot_keys:
            try:
                with winreg.OpenKey(hive, path):
                    reasons.append("composants Windows en attente")
                    break
            except OSError:
                continue

        if reasons:
            self.log(
                "REDÉMARRAGE REQUIS (" + ", ".join(dict.fromkeys(reasons)) + ") — "
                "redémarrez la machine après vérification.", "WARN"
            )
        else:
            self.log("Aucun redémarrage nécessaire détecté.", "OK")


# ═══════════════════════════════════════════════════════════════════════════════
# FENÊTRE DE CONFIGURATION INITIALE
# ═══════════════════════════════════════════════════════════════════════════════

class SetupDialog(QWidget):
    """Formulaire de saisie des infos machine avant le lancement."""

    accepted = pyqtSignal(dict)

    def __init__(self):
        super().__init__()
        self.setWindowTitle("LGS InstalleX — Configuration initiale")
        self.setFixedSize(480, 260)
        self._build_ui()
        self._apply_style()

    def _build_ui(self):
        layout = QVBoxLayout(self)
        layout.setSpacing(12)
        layout.setContentsMargins(20, 20, 20, 20)

        title = QLabel(f"LGS InstalleX v{INSTALLEX_VERSION} — Informations de provisioning")
        title.setFont(QFont("Segoe UI", 12, QFont.Weight.Bold))
        title.setAlignment(Qt.AlignmentFlag.AlignCenter)
        layout.addWidget(title)

        form = QFormLayout()
        form.setLabelAlignment(Qt.AlignmentFlag.AlignRight)

        self.txt_name = QLineEdit()
        self.txt_name.setPlaceholderText("ex: LGSPC-00123")
        # Pré-remplissage par la configuration externe si elle fournit un nom,
        # sinon nom actuel du poste. Le champ reste modifiable dans tous les cas.
        self.txt_name.setText(CONFIG.get("computer_name") or platform.node())
        form.addRow("Nouveau nom d'ordinateur :", self.txt_name)

        self.chk_nouvelle_embauche = QCheckBox("Nouvelle embauche")
        self.chk_nouvelle_embauche.setChecked(bool(CONFIG.get("nouvelle_embauche")))
        form.addRow("", self.chk_nouvelle_embauche)

        layout.addLayout(form)

        btn = QPushButton("🚀  Démarrer l'installation")
        btn.setFixedHeight(40)
        btn.setFont(QFont("Segoe UI", 10, QFont.Weight.Bold))
        btn.clicked.connect(self._launch)
        layout.addWidget(btn)
        self._btn = btn

    def _apply_style(self):
        self.setStyleSheet(f"""
            QWidget {{
                background-color: {CLR_BG};
                color: {CLR_TEXT_MAIN};
                font-family: 'Segoe UI';
                font-size: 9pt;
            }}
            QLineEdit {{
                background: {CLR_BG2};
                border: 1px solid {CLR_BORDER};
                border-radius: 4px;
                padding: 4px 8px;
                color: {CLR_TEXT_WHITE};
            }}
            QPushButton {{
                background: {CLR_ACCENT};
                border: none;
                border-radius: 6px;
                color: white;
            }}
            QPushButton:hover {{
                background: {CLR_ACCENT2};
            }}
            QCheckBox {{
                color: {CLR_TEXT_MUTED};
            }}
        """)

    def _launch(self):
        name = self.txt_name.text().strip()

        # Validation NetBIOS : 1–15 caractères, lettres/chiffres/tirets uniquement.
        # Un nom vide est accepté (l'étape 4 ignorera alors le renommage).
        # Doit rester STRICTEMENT identique à la regex de step4_computer_name.
        if name and not re.fullmatch(r"[A-Za-z0-9-]{1,15}", name):
            QMessageBox.warning(
                self,
                "Nom invalide",
                "Le nom d'ordinateur doit contenir uniquement des lettres, chiffres\n"
                "et tirets, avec 15 caractères maximum.\n\n"
                f"Valeur saisie : « {name} »"
            )
            self.txt_name.setFocus()
            self.txt_name.selectAll()
            return

        info = {
            "computer_name":     name,
            "nouvelle_embauche": self.chk_nouvelle_embauche.isChecked(),
        }
        self.accepted.emit(info)
        self.hide()  # hide() au lieu de close() — évite lastWindowClosed avant que InstalleXWindow soit visible

    def closeEvent(self, event):
        """Fermeture manuelle du SetupDialog (croix) sans avoir cliqué Démarrer → quitter."""
        event.accept()
        QApplication.instance().quit()


# ═══════════════════════════════════════════════════════════════════════════════
# PANNEAU D'UNE ÉTAPE
# ═══════════════════════════════════════════════════════════════════════════════

class StepPanel(QFrame):
    def __init__(self, name: str):
        super().__init__()
        self.setFixedHeight(55)
        self._build(name)
        self._set_state("pending")

    def _build(self, name: str):
        self.ind   = QFrame(self)
        self.ind.setGeometry(0, 0, 4, 55)

        self.lbl_icon = QLabel("○", self)
        self.lbl_icon.setGeometry(8, 12, 24, 30)
        self.lbl_icon.setFont(QFont("Segoe UI", 13))
        self.lbl_icon.setAlignment(Qt.AlignmentFlag.AlignCenter)

        self.lbl_name = QLabel(name, self)
        self.lbl_name.setGeometry(36, 10, 390, 20)
        self.lbl_name.setFont(QFont("Segoe UI", 9))

        self.lbl_detail = QLabel("En attente", self)
        self.lbl_detail.setGeometry(36, 32, 390, 16)
        self.lbl_detail.setFont(QFont("Segoe UI", 8))

        sep = QFrame(self)
        sep.setGeometry(0, 54, 430, 1)
        sep.setStyleSheet(f"background:{CLR_BG};")

    def _set_state(self, state: str, detail: str = ""):
        colours = {
            "pending": (CLR_BORDER, CLR_BORDER,     "○", CLR_TEXT_MUTED, CLR_TEXT_MUTED),
            "active":  (CLR_ACCENT, CLR_STEP_ACT,   "⟳", CLR_ACCENT,     CLR_TEXT_WHITE),
            "done":    (CLR_OK,     CLR_STEP_DONE,  "✓", CLR_OK,          CLR_TEXT_WHITE),
            "fail":    (CLR_FAIL,   CLR_BG,         "✗", CLR_FAIL,        CLR_TEXT_WHITE),
            "skip":    (CLR_SKIP,   CLR_BG,         "⏭", CLR_SKIP,        CLR_TEXT_MAIN),
        }
        ind_c, bg_c, icon, icon_c, txt_c = colours.get(state, colours["pending"])
        self.ind.setStyleSheet(f"background:{ind_c};")
        self.setStyleSheet(f"background:{bg_c};")
        self.lbl_icon.setText(icon)
        self.lbl_icon.setStyleSheet(f"color:{icon_c}; background:transparent;")
        # Couleur du titre TOUJOURS explicite : sans ça, appliquer un fond à
        # StepPanel réinitialise la couleur héritée des labels → texte noir
        # illisible sur le vert « done ».
        self.lbl_name.setStyleSheet(f"color:{txt_c}; background:transparent;")
        if detail:
            self.lbl_detail.setText(detail)
        self.lbl_detail.setStyleSheet(f"color:{txt_c}; background:transparent;")

    def update_state(self, state: str, detail: str = ""):
        self._set_state(state, detail)


