class InstalleXWindow(QMainWindow):
    def __init__(self, machine_info: dict, build: str, version: str):
        super().__init__()
        self.machine_info = machine_info
        self.win_build    = build
        self.win_version  = version
        self.step_panels: list[StepPanel] = []

        self.setWindowTitle("LGS InstalleX — Provisionnement automatise des postes de travail")
        self.setFixedSize(860, 696)

        # Empêcher Qt de détruire la fenêtre automatiquement sur un signal
        # système (WM_ENDSESSION après Rename-Computer). Toute fermeture
        # passe par closeEvent() qui demande confirmation.
        self.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, False)

        self._build_ui()
        self._apply_global_style()
        # Icône de fenêtre depuis le même LOGO_B64 que le PS1
        try:
            _icon_bytes = base64.b64decode(LOGO_B64)
            _icon_pix   = QPixmap()
            _icon_pix.loadFromData(_icon_bytes)
            self.setWindowIcon(QIcon(_icon_pix))
        except Exception:
            pass
        self._start_install()

    # ── construction UI ───────────────────────────────────────────────────────

    def _build_ui(self):
        central = QWidget()
        self.setCentralWidget(central)
        root = QVBoxLayout(central)
        root.setContentsMargins(0, 0, 0, 0)
        root.setSpacing(0)

        root.addWidget(self._make_header())
        root.addWidget(self._make_progress_bar())
        root.addWidget(self._make_steps_grid())
        root.addWidget(self._make_log_panel())
        root.addWidget(self._make_footer())

    def _make_header(self) -> QWidget:
        pnl = QWidget()
        pnl.setFixedHeight(72)
        pnl.setStyleSheet(f"background:{CLR_HEADER};")
        lay = QHBoxLayout(pnl)
        lay.setContentsMargins(14, 10, 14, 10)

        # Logo — chargé depuis LOGO_B64 (même source que le PS1)
        lbl_logo = QLabel()
        lbl_logo.setFixedSize(52, 52)
        lbl_logo.setStyleSheet(f"background:{CLR_HEADER};")
        try:
            _logo_bytes = base64.b64decode(LOGO_B64)
            _logo_pix   = QPixmap()
            _logo_pix.loadFromData(_logo_bytes)
            lbl_logo.setPixmap(_logo_pix.scaled(
                52, 52,
                Qt.AspectRatioMode.KeepAspectRatio,
                Qt.TransformationMode.SmoothTransformation
            ))
        except Exception:
            pass
        lay.addWidget(lbl_logo)

        # Titres
        txt = QVBoxLayout()
        txt.setSpacing(2)
        lbl_title = QLabel("Script d'automatisation de configuration (LGS InstalleX)")
        lbl_title.setFont(QFont("Segoe UI", 12))
        lbl_title.setStyleSheet(f"color:{CLR_TEXT_MAIN};")
        txt.addWidget(lbl_title)

        lbl_sub = QLabel(f"© Copyright Groupe LGS — une Société IBM   | v{INSTALLEX_VERSION}")
        lbl_sub.setFont(QFont("Segoe UI", 8))
        lbl_sub.setStyleSheet(f"color:{CLR_TEXT_MUTED};")
        txt.addWidget(lbl_sub)
        lay.addLayout(txt)

        lay.addStretch()

        # Infos machine
        cn  = self.machine_info.get("computer_name") or platform.node()
        usr = os.environ.get("USERNAME", "Inconnu")
        lbl_machine = QLabel(
            f"{cn}\n{usr}\nWindows {self.win_version} ({self.win_build})"
        )
        lbl_machine.setFont(QFont("Segoe UI", 8))
        lbl_machine.setStyleSheet(f"color:{CLR_TEXT_MUTED};")
        lbl_machine.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
        lay.addWidget(lbl_machine)
        return pnl

    def _make_progress_bar(self) -> QWidget:
        pnl = QWidget()
        pnl.setFixedHeight(48)
        pnl.setStyleSheet(f"background:{CLR_BG2};")
        lay = QVBoxLayout(pnl)
        lay.setContentsMargins(14, 8, 14, 8)
        lay.setSpacing(4)

        top = QHBoxLayout()
        self.lbl_progress_label = QLabel("Initialisation…")
        self.lbl_progress_label.setFont(QFont("Segoe UI", 9))
        self.lbl_progress_label.setStyleSheet(f"color:{CLR_TEXT_MUTED};")
        top.addWidget(self.lbl_progress_label)
        top.addStretch()

        self.lbl_progress_pct = QLabel("0 %")
        self.lbl_progress_pct.setFont(QFont("Segoe UI", 9, QFont.Weight.Bold))
        self.lbl_progress_pct.setStyleSheet(f"color:{CLR_ACCENT};")
        top.addWidget(self.lbl_progress_pct)
        lay.addLayout(top)

        self.progress_bar = QProgressBar()
        self.progress_bar.setFixedHeight(6)
        self.progress_bar.setTextVisible(False)
        self.progress_bar.setRange(0, 100)
        self.progress_bar.setValue(0)
        self.progress_bar.setStyleSheet(f"""
            QProgressBar {{
                border: none;
                background: {CLR_BG3};
                border-radius: 3px;
            }}
            QProgressBar::chunk {{
                background: {CLR_ACCENT};
                border-radius: 3px;
            }}
        """)
        lay.addWidget(self.progress_bar)
        return pnl

    def _make_steps_grid(self) -> QWidget:
        pnl = QWidget()
        pnl.setFixedHeight(336)
        pnl.setStyleSheet(f"background:{CLR_BG};")
        lay = QWidget(pnl)
        lay.setGeometry(0, 0, 860, 336)

        for i, name in enumerate(STEPS):
            col = i % 2
            row = i // 2
            x   = 0 if col == 0 else 430
            y   = row * 56
            sp  = StepPanel(name)
            sp.setParent(pnl)
            sp.setGeometry(x, y, 430, 55)
            sp.show()
            self.step_panels.append(sp)

        return pnl

    def _make_log_panel(self) -> QWidget:
        pnl = QWidget()
        pnl.setFixedHeight(148)
        pnl.setStyleSheet(f"background:{CLR_BG3};")
        v = QVBoxLayout(pnl)
        v.setContentsMargins(14, 5, 14, 5)

        lbl = QLabel("JOURNAL EN TEMPS RÉEL")
        lbl.setFont(QFont("Segoe UI", 7))
        lbl.setStyleSheet(f"color:{CLR_TEXT_MUTED};")
        v.addWidget(lbl)

        self.txt_log = QTextEdit()
        self.txt_log.setReadOnly(True)
        self.txt_log.setFont(QFont("Consolas", 8))
        self.txt_log.setStyleSheet(f"""
            QTextEdit {{
                background: {CLR_BG3};
                color: {CLR_TEXT_WHITE};
                border: none;
            }}
        """)
        v.addWidget(self.txt_log)
        return pnl

    def _make_footer(self) -> QWidget:
        pnl = QWidget()
        pnl.setFixedHeight(36)
        pnl.setStyleSheet(f"background:{CLR_BG2};")
        lay = QHBoxLayout(pnl)
        lay.setContentsMargins(14, 0, 14, 0)
        lay.setSpacing(10)

        self.lbl_footer = QLabel(
            "© Copyright Kevin Laplante pour Groupe LGS  |  LGS InstalleX v" + INSTALLEX_VERSION
        )
        self.lbl_footer.setFont(QFont("Segoe UI", 7))
        self.lbl_footer.setStyleSheet(f"color:{CLR_TEXT_MUTED};")
        lay.addWidget(self.lbl_footer)
        lay.addStretch()

        # Bouton "Ouvrir le log" — caché jusqu'à la fin de l'installation
        self.btn_open_log = QPushButton("📋  Ouvrir le log")
        self.btn_open_log.setFixedHeight(24)
        self.btn_open_log.setFont(QFont("Segoe UI", 8))
        self.btn_open_log.setStyleSheet(f"""
            QPushButton {{
                background: {CLR_ACCENT};
                border: none;
                border-radius: 4px;
                color: white;
                padding: 0 10px;
            }}
            QPushButton:hover {{ background: {CLR_ACCENT2}; }}
        """)
        self.btn_open_log.clicked.connect(self._open_log)
        self.btn_open_log.hide()
        lay.addWidget(self.btn_open_log)

        self.lbl_status = QLabel("En cours…")
        self.lbl_status.setFont(QFont("Segoe UI", 7))
        self.lbl_status.setStyleSheet(f"color:{CLR_ACCENT};")
        lay.addWidget(self.lbl_status)
        return pnl

    def _apply_global_style(self):
        self.setStyleSheet(f"QMainWindow {{ background:{CLR_BG}; }}")

    def closeEvent(self, event):
        """Intercepte la fermeture de fenêtre.
        - Si le worker tourne : demande confirmation, puis arrêt propre + sys.exit.
        - Si le worker est terminé : fermeture directe.
        """
        if hasattr(self, "worker") and self.worker.isRunning():
            rep = QMessageBox.question(
                self,
                "Interrompre l'installation ?",
                "L'installation est en cours.\n\n"
                "Fermer maintenant va interrompre le script et quitter complètement.\n"
                "Êtes-vous sûr ?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No,
            )
            if rep != QMessageBox.StandardButton.Yes:
                event.ignore()
                return
            # Arrêt propre : signaler le worker, débloquer toute pause en attente,
            # attendre max 3 s que le thread termine, puis forcer la sortie.
            self.worker.request_stop()
            self.worker.wait(3000)  # ms
        event.accept()
        sys.exit(0)

    # ── démarrage du thread ───────────────────────────────────────────────────

    def _start_install(self):
        self.worker = InstallWorker(self.machine_info)
        self.worker.sig_log.connect(self._on_log)
        self.worker.sig_step.connect(self._on_step)
        self.worker.sig_progress.connect(self._on_progress)
        self.worker.sig_done.connect(self._on_done)
        self.worker.sig_pause.connect(self._on_pause)

        # Étape 0 déjà faite (diagnostic système)
        self.step_panels[0].update_state(
            "done", f"Build {self.win_build} — {self.win_version}"
        )
        self._on_progress(1, "Étape 1/11 — Création des dossiers")

        self.worker.start()

    # ── slots ─────────────────────────────────────────────────────────────────

    LEVEL_COLORS = {
        "OK":   CLR_OK,
        "WARN": CLR_WARN,
        "FAIL": CLR_FAIL,
        "SKIP": CLR_SKIP,
        "CMD":  CLR_TEXT_MUTED,
        "INFO": CLR_TEXT_WHITE,
        "SECTION": CLR_ACCENT,
    }

    def _on_log(self, msg: str, level: str):
        color = self.LEVEL_COLORS.get(level, CLR_TEXT_WHITE)
        ts    = datetime.now().strftime("%H:%M:%S")
        html  = (
            f'<span style="color:{CLR_TEXT_MUTED};">{ts}</span> '
            f'<span style="color:{color};">{msg}</span>'
        )
        self.txt_log.append(html)
        sb = self.txt_log.verticalScrollBar()
        sb.setValue(sb.maximum())

    def _on_step(self, idx: int, state: str, detail: str):
        if 0 <= idx < len(self.step_panels):
            self.step_panels[idx].update_state(state, detail)

    def _on_progress(self, pct: int, label: str):
        # pct ici = numéro d'étape (1–11) converti en %
        real_pct = min(int((pct / 11) * 100), 100)
        self.progress_bar.setValue(real_pct)
        self.lbl_progress_pct.setText(f"{real_pct} %")
        self.lbl_progress_label.setText(label)

    def _on_pause(self, titre: str, message: str):
        """Slot GUI : affiche une QMessageBox bloquante, puis débloque le worker."""
        QMessageBox.information(self, titre, message)
        self.worker.resume()

    def _on_done(self):
        self.lbl_status.setText("✅ Installation terminée !")
        self.lbl_status.setStyleSheet(f"color:{CLR_OK};")
        self.btn_open_log.show()
        self._show_completion_beep()

    def _open_log(self):
        """Ouvre le fichier log directement depuis Windows Explorer."""
        try:
            log_path = self.worker.log_path
            if log_path and Path(log_path).exists():
                os.startfile(log_path)
            else:
                QMessageBox.warning(self, "Log introuvable",
                                    "Le fichier log est introuvable.\n"
                                    "Emplacement attendu : le bureau.")
        except Exception as exc:
            QMessageBox.warning(self, "Erreur", f"Impossible d'ouvrir le log :\n{exc}")

    def _show_completion_beep(self):
        """Bips de fin (équivalent PowerShell [console]::beep)."""
        def beep_loop():
            for _ in range(5):
                try:
                    import winsound
                    winsound.Beep(1000, 200)
                    time.sleep(0.1)
                    winsound.Beep(1000, 200)
                    time.sleep(0.1)
                    winsound.Beep(1000, 200)
                    time.sleep(0.8)
                except Exception:
                    break
        threading.Thread(target=beep_loop, daemon=True).start()


# ═══════════════════════════════════════════════════════════════════════════════
# POINT D'ENTRÉE
# ═══════════════════════════════════════════════════════════════════════════════

def main():
    import traceback

    _crash_log = Path(tempfile.gettempdir()) / "InstalleX_crash.log"

    def _write_crash(text: str):
        try:
            with open(_crash_log, "a", encoding="utf-8-sig") as f:
                f.write(text + "\n")
            os.startfile(_crash_log)
        except Exception:
            pass

    # Capture les exceptions non gérées dans le thread principal
    def _excepthook(exc_type, exc_value, exc_tb):
        msg = "".join(traceback.format_exception(exc_type, exc_value, exc_tb))
        _write_crash(f"[EXCEPTHOOK]\n{msg}")

    sys.excepthook = _excepthook

    # Capture les exceptions non gérées dans les threads secondaires (worker)
    def _threading_excepthook(args):
        msg = "".join(traceback.format_exception(args.exc_type, args.exc_value, args.exc_traceback))
        _write_crash(f"[THREAD EXCEPTHOOK — {args.thread}]\n{msg}")

    threading.excepthook = _threading_excepthook
    # Vérification admin
    if not is_admin():
        print("Relancement avec droits administrateur…")
        relaunch_as_admin()
        return

    app = QApplication(sys.argv)
    app.setStyle("Fusion")

    # Désactiver la fermeture automatique quand la dernière fenêtre se ferme.
    # Sans ça, Windows peut envoyer WM_ENDSESSION (ex: après Rename-Computer)
    # et Qt quitte dès que la fenêtre SetupDialog disparaît.
    app.setQuitOnLastWindowClosed(False)

    # Diagnostic système (avant GUI)
    build, version = get_windows_build()

    # ── Dialogue de configuration ─────────────────────────────────────────────
    setup = SetupDialog()
    machine_info: dict = {}

    def on_accepted(info: dict):
        nonlocal machine_info
        machine_info = info
        win = InstalleXWindow(info, build, version)
        app._installex_win = win  # empêche le garbage collector de détruire la fenêtre
        win.show()

    setup.accepted.connect(on_accepted)
    setup.show()

    # Une seule boucle d'événements pour toute la durée du programme.
    sys.exit(app.exec())


if __name__ == "__main__":
    import traceback
    _crash_log = Path(tempfile.gettempdir()) / "InstalleX_crash.log"
    try:
        main()
    except Exception:
        _crash_log.write_text(traceback.format_exc(), encoding="utf-8-sig")
        try:
            os.startfile(_crash_log)
        except Exception:
            pass
        raise
